1	// Package xregistry is a read-only client for the Intropy xRegistry
2	// service: message, endpoint, and schema discovery over GET /export, plus
3	// in-memory resolution of a message reference into the wiring a component
4	// needs to subscribe to it.
5	//
6	// It shares a name and nothing else with internal/registry, the OCI
7	// registry client — different protocol, different base URL, different
8	// failure model. The two packages are unrelated and must not borrow each
9	// other's types; a rename of one is not a rename of the other.
10	//
11	// xRegistry has no message-to-channel field: the association is
12	// Endpoint.messagegroups (the groups allowed on an endpoint) plus
13	// Endpoint.channel, and the resolution join in resolve.go walks it. The
14	// registry declares filtering, inlining, entity-path lookups, and pagination
15	// out of scope, so the client sends only GET /export — no query params it
16	// did not see advertised.
17	package xregistry
18	
19	import (
20		"context"
21		"encoding/json"
22		"fmt"
23		"io"
24		"net/http"
25		"net/url"
26		"sort"
27		"strings"
28		"time"
29	)
30	
31	// Client speaks to one read-only xRegistry service. Construct with New;
32	// methods take a context first and never retry internally. The default
33	// HTTP client has a timeout — tighter or looser policies (and tests)
34	// pass WithHTTPClient.
35	type Client struct {
36		base       *url.URL
37		httpClient *http.Client
38		userAgent  string
39	}
40	
41	const defaultHTTPTimeout = 15 * time.Second
42	
43	type options struct {
44		httpClient *http.Client
45		userAgent  string
46	}
47	
48	// Option customises New.
49	type Option func(*options)
50	
51	// WithHTTPClient replaces the default client. Tests inject an httptest
52	// transport here.
53	func WithHTTPClient(c *http.Client) Option {
54		return func(o *options) { o.httpClient = c }
55	}
56	
57	// WithUserAgent sets the User-Agent header on every request.
58	func WithUserAgent(ua string) Option {
59		return func(o *options) { o.userAgent = ua }
60	}
61	
62	// New builds a Client for the service at baseURL. The base URL must parse
63	// and be absolute: a relative base would make every request path a guess.
64	func New(baseURL string, opts ...Option) (*Client, error) {
65		u, err := url.Parse(strings.TrimSuffix(baseURL, "/"))
66		if err != nil {
67			return nil, fmt.Errorf("parse xRegistry base URL %q: %w", baseURL, err)
68		}
69		if !u.IsAbs() {
70			return nil, fmt.Errorf("xRegistry base URL %q is not absolute", baseURL)
71		}
72		o := options{httpClient: &http.Client{Timeout: defaultHTTPTimeout}}
73		for _, opt := range opts {
74			opt(&o)
75		}
76		return &Client{base: u, httpClient: o.httpClient, userAgent: o.userAgent}, nil
77	}
78	
79	// BaseURL reports the service root the client was built against, without
80	// a trailing slash.
81	func (c *Client) BaseURL() string { return c.base.String() }
82	
83	// get issues one GET and decodes the JSON body into out. Error bodies are
84	// the xRegistry error document; both the transport error and the body are
85	// surfaced so the caller can front-load what failed.
86	func (c *Client) get(ctx context.Context, path string, out any) error {
87		u := c.base.JoinPath(path)
88		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
89		if err != nil {
90			return fmt.Errorf("build request for %s: %w", path, err)
91		}
92		req.Header.Set("Accept", "application/json")
93		if c.userAgent != "" {
94			req.Header.Set("User-Agent", c.userAgent)
95		}
96		resp, err := c.httpClient.Do(req)
97		if err != nil {
98			return fmt.Errorf("GET %s: %w", u.String(), err)
99		}
100		defer resp.Body.Close()
101		body, err := io.ReadAll(io.LimitReader(resp.Body, maxBodyBytes))
102		if err != nil {
103			return fmt.Errorf("read %s: %w", u.String(), err)
104		}
105		if resp.StatusCode != http.StatusOK {
106			return fmt.Errorf("GET %s: registry returned %s: %s", u.String(), resp.Status, errorBody(body))
107		}
108		if err := json.Unmarshal(body, out); err != nil {
109			return fmt.Errorf("parse %s: %w", u.String(), err)
110		}
111		return nil
112	}
113	
114	// maxBodyBytes bounds a response read. The export of a registry that grew
115	// past this size is itself an operational problem — silently truncating a
116	// resolution input would be worse than failing loudly.
117	const maxBodyBytes = 64 << 20
118	
119	// errorBody condenses an xRegistry error document ({code, detail, status})
120	// into one line; a body that does not parse is shown truncated as-is.
121	func errorBody(body []byte) string {
122		var doc struct {
123			Code   string `json:"code"`
124			Detail string `json:"detail"`
125		}
126		if err := json.Unmarshal(body, &doc); err == nil && doc.Code != "" {
127			if doc.Detail != "" {
128				return doc.Code + ": " + doc.Detail
129			}
130			return doc.Code
131		}
132		const maxLen = 200
133		s := string(body)
134		if len(s) > maxLen {
135			s = s[:maxLen] + "…"
136		}
137		return s
138	}
139	
140	// Export fetches the complete registry document. One call, no walk: the
141	// service guarantees /export contains the message, endpoint, and schema
142	// views the CLI needs.
143	func (c *Client) Export(ctx context.Context) (*Export, error) {
144		var doc Export
145		if err := c.get(ctx, "/export", &doc); err != nil {
146			return nil, fmt.Errorf("fetch xRegistry export: %w", err)
147		}
148		return &doc, nil
149	}
150	
151	// DefaultMessage resolves a message's definition attributes from the doc
152	// view, where they live on the single implicit version.
153	func (m *Message) DefaultMessage() *MessageVersion {
154		if len(m.Versions) == 0 {
155			return nil
156		}
157		// Prefer an explicit default; a document without isdefault markers
158		// (none this service emits) falls back to the lowest version id so the
159		// result never depends on map iteration order.
160		ids := make([]string, 0, len(m.Versions))
161		for id := range m.Versions {
162			ids = append(ids, id)
163		}
164		sort.Strings(ids)
165		var fallback *MessageVersion
166		for _, id := range ids {
167			v := m.Versions[id]
168			if v.IsDefault {
169				return v
170			}
171			if fallback == nil {
172				fallback = v
173			}
174		}
175		return fallback
176	}
