1	package xregistry
2	
3	import (
4		"context"
5		"fmt"
6		"sort"
7		"strings"
8	)
9	
10	// Channel is one producing channel: the pub/sub component and topic an
11	// event flows through, as split from the endpoint's <pubsub>/<topic>
12	// channel string.
13	type Channel struct {
14		Pubsub   string
15		Topic    string
16		Endpoint string
17	}
18	
19	// ResolvedMessage is the wiring --subscribe writes into a scaffold record:
20	// the message identity, its CloudEvents type, the channels the message can
21	// arrive on, and the schema pin.
22	type ResolvedMessage struct {
23		// Message is the message id, which for these registries doubles as the
24		// CloudEvents type — the registry constrains envelopemetadata.type to
25		// the same dotted name. Type carries the envelope value verbatim; the
26		// two are distinct fields so a registry that ever diverges them stays
27		// representable.
28		Message string
29		Type    string
30		Group   string
31	
32		// Channels is the set of producer endpoints' channels for the message's
33		// group, split and sorted. Exactly one is the subscribe channel; more
34		// is AmbiguousProducerError, none is NoProducerError.
35		Channels []Channel
36	
37		// DataSchema is the logical schema xid from the message definition;
38		// DataSchemaURL pins the schema's default version — an immutable URL —
39		// at subscribe time.
40		DataSchema    string
41		DataSchemaURL string
42	}
43	
44	// ResolveMessage resolves one message reference — a bare message id or a
45	// full /messagegroups/<gid>/messages/<mid> xid — against the export
46	// document into subscription wiring. All joins are in memory: nothing but
47	// the export is fetched.
48	//
49	// The resolution the caller cannot do without: message → group → producer
50	// endpoints → channel split, plus dataschemaxid → default version URL.
51	func ResolveMessage(doc *Export, ref string) (*ResolvedMessage, error) {
52		msg, group, err := findMessage(doc, ref)
53		if err != nil {
54			return nil, err
55		}
56		dflt := msg.DefaultMessage()
57		if dflt == nil {
58			return nil, &NoDefaultVersionError{Ref: ref, Group: group.ID}
59		}
60	
61		res := &ResolvedMessage{
62			Message: msg.ID,
63			Group:   group.ID,
64		}
65		if attr, ok := dflt.EnvelopeMetadata["type"]; ok {
66			if s, ok := attr.Value.(string); ok {
67				res.Type = s
68			}
69		}
70		res.DataSchema = dflt.DataSchemaXID
71		if res.DataSchema != "" {
72			xid, err := DefaultSchemaVersionXID(doc, res.DataSchema)
73			if err != nil {
74				return nil, err
75			}
76			// Root-relative xid: the caller (Client.Resolve) joins it with the
77			// base URL; a bare ResolveMessage on a hand-built doc keeps the xid.
78			res.DataSchemaURL = xid
79		}
80	
81		channels, err := producerChannels(doc, group.ID)
82		if err != nil {
83			return nil, err
84		}
85		res.Channels = channels
86		return res, nil
87	}
88	
89	// SubscribeChannel picks the one channel of a resolved message. The choice
90	// is the caller's only when several producers carry the group on different
91	// channels — the interactive pick list and the --no-input error both
92	// consume the full Channels list, so it is kept there.
93	func (r *ResolvedMessage) SubscribeChannel() (Channel, error) {
94		switch len(r.Channels) {
95		case 0:
96			return Channel{}, &NoProducerError{Group: r.Group}
97		case 1:
98			return r.Channels[0], nil
99		default:
100			return Channel{}, &AmbiguousProducerError{Ref: r.Message, Channels: r.Channels}
101		}
102	}
103	
104	// FindMessage locates one message by reference — a bare message id
105	// (unique across groups) or a full /messagegroups/<gid>/messages/<mid>
106	// xid — and returns it with its group. Exported for display surfaces; the
107	// ambiguity and not-found failures are the typed errors.
108	func FindMessage(doc *Export, ref string) (*Message, *MessageGroup, error) {
109		return findMessage(doc, ref)
110	}
111	
112	func findMessage(doc *Export, ref string) (*Message, *MessageGroup, error) {
113		if ref == "" {
114			return nil, nil, fmt.Errorf("message reference is empty")
115		}
116		if xid, ok := strings.CutPrefix(ref, "/messagegroups/"); ok {
117			gid, mid, ok := strings.Cut(xid, "/messages/")
118			if !ok || gid == "" || mid == "" {
119				return nil, nil, fmt.Errorf("message reference %q is not a message id or /messagegroups/<gid>/messages/<mid> xid", ref)
120			}
121			g, ok := doc.MessageGroups[gid]
122			if !ok {
123				return nil, nil, &MessageNotFoundError{Ref: ref}
124			}
125			m, ok := g.Messages[mid]
126			if !ok {
127				return nil, nil, &MessageNotFoundError{Ref: ref}
128			}
129			return &m, &g, nil
130		}
131	
132		var found *Message
133		var group *MessageGroup
134		for i := range doc.MessageGroups {
135			g := doc.MessageGroups[i]
136			if m, ok := g.Messages[ref]; ok {
137				if found != nil {
138					xids := messageGroupXIDs(doc, ref)
139					return nil, nil, fmt.Errorf("message reference %q is ambiguous: declared in groups %s", ref, strings.Join(xids, ", "))
140				}
141				mCopy, gCopy := m, g
142				found, group = &mCopy, &gCopy
143			}
144		}
145		if found == nil {
146			return nil, nil, &MessageNotFoundError{Ref: ref}
147		}
148		return found, group, nil
149	}
150	
151	// messageGroupXIDs names the groups carrying ref, for the ambiguity error.
152	func messageGroupXIDs(doc *Export, ref string) []string {
153		var out []string
154		for _, g := range doc.MessageGroups {
155			if _, ok := g.Messages[ref]; ok {
156				out = append(out, "/messagegroups/"+g.ID)
157			}
158		}
159		sort.Strings(out)
160		return out
161	}
162	
163	// producerChannels joins the group to its producer endpoints and splits
164	// each channel. Endpoints whose usage omits "producer" are subscriptions
165	// and consumers, never the resolution answer.
166	func producerChannels(doc *Export, groupID string) ([]Channel, error) {
167		want := "/messagegroups/" + groupID
168		var channels []Channel
169		for _, e := range doc.Endpoints {
170			if !slicesContain(e.Usage, "producer") {
171				continue
172			}
173			if !slicesContain(e.MessageGroups, want) {
174				continue
175			}
176			pubsub, topic, err := SplitChannel(e.Channel)
177			if err != nil {
178				return nil, &ChannelFormatError{Endpoint: e.ID, Channel: e.Channel, err: err}
179			}
180			channels = append(channels, Channel{Pubsub: pubsub, Topic: topic, Endpoint: e.ID})
181		}
182		sort.Slice(channels, func(i, j int) bool {
183			if channels[i].Pubsub != channels[j].Pubsub {
184				return channels[i].Pubsub < channels[j].Pubsub
185			}
186			return channels[i].Topic < channels[j].Topic
187		})
188		return channels, nil
189	}
190	
191	// Resolve fetches the export and resolves one message reference into
192	// subscription wiring — the flow --subscribe runs. The schema pin is
193	// returned absolute: the pinned version URL must survive on its own once
194	// the record is committed, so it is joined with the base URL here.
195	func (c *Client) Resolve(ctx context.Context, ref string) (*ResolvedMessage, error) {
196		doc, err := c.Export(ctx)
197		if err != nil {
198			return nil, err
199		}
200		res, err := ResolveMessage(doc, ref)
201		if err != nil {
202			return nil, err
203		}
204		if res.DataSchemaURL != "" {
205			if u, err := c.base.Parse(strings.TrimPrefix(res.DataSchemaURL, "/")); err == nil {
206				res.DataSchemaURL = u.String()
207			}
208		}
209		return res, nil
210	}
211	
212	// SplitChannel splits an endpoint channel into its pub/sub component and
213	// topic halves. The format belongs to the registry's conformance suite;
214	// this validates and fails naming the endpoint rather than accepting a
215	// half-parsed channel.
216	func SplitChannel(channel string) (pubsub, topic string, err error) {
217		pubsub, topic, ok := strings.Cut(channel, "/")
218		if !ok || strings.TrimSpace(pubsub) == "" || strings.TrimSpace(topic) == "" {
219			return "", "", fmt.Errorf("channel %q is not <pubsub>/<topic>", channel)
220		}
221		return pubsub, topic, nil
222	}
223	
224	// DefaultSchemaVersionXID pins a logical schema xid to its default
225	// version's xid — the immutable form a CloudEvent dataschema references.
226	// Exported for callers that already hold the export document and resolve
227	// display data (URLs, names) without a second round-trip.
228	func DefaultSchemaVersionXID(doc *Export, xid string) (string, error) {
229		gid, sid, ok := splitSchemaXID(xid)
230		if !ok {
231			return "", &SchemaNotFoundError{XID: xid}
232		}
233		g, ok := doc.SchemaGroups[gid]
234		if !ok {
235			return "", &SchemaNotFoundError{XID: xid}
236		}
237		s, ok := g.Schemas[sid]
238		if !ok {
239			return "", &SchemaNotFoundError{XID: xid}
240		}
241		for _, v := range s.Versions {
242			if v.IsDefault {
243				return v.XID, nil
244			}
245		}
246		return "", &SchemaNotFoundError{XID: xid}
247	}
248	
249	// splitSchemaXID parses /schemagroups/<gid>/schemas/<sid>.
250	func splitSchemaXID(xid string) (gid, sid string, ok bool) {
251		rest, ok := strings.CutPrefix(xid, "/schemagroups/")
252		if !ok {
253			return "", "", false
254		}
255		gid, sid, ok = strings.Cut(rest, "/schemas/")
256		if !ok || gid == "" || sid == "" {
257			return "", "", false
258		}
259		return gid, sid, true
260	}
261	
262	func slicesContain(list []string, want string) bool {
263		for _, s := range list {
264			if s == want {
265				return true
266			}
267		}
268		return false
269	}
