package template

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
	"text/template"

	"github.com/Masterminds/sprig/v3"
	"github.com/santhosh-tekuri/jsonschema/v5"
	"gopkg.in/yaml.v3"
)

// StdinValuesPath is the sentinel a caller may pass in the values-file list
// to signal "read a single values document from this reader". It mirrors the
// `-f -` idiom used by helm, kubectl, and curl.
const StdinValuesPath = "-"

// Resolve produces the final value map by layering, in order:
//
//	defaults declared in spec.parameters.properties[*].default
//	--values files (in supplied order; "-" reads one doc from stdin)
//	--set flags (string values, coerced to declared JSON Schema types)
//	prompts for required parameters still missing (when prompter != nil)
//
// stdin is consumed at most once across the files list; passing "-" twice is
// an error. The merged map is then validated against the JSON Schema in
// spec.parameters. Finally, every entry in spec.values is rendered as a Go
// text/template (with sprig) against the merged map and added under its key.
// A spec.values key that collides with a parameter name is rejected.
func Resolve(t *Template, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	return ResolveWith(t, ResolveOptions{Files: files, Stdin: stdin, Sets: sets, Prompter: prompter})
}

// ResolveLayered is Resolve with an extra base layer that sits between the
// spec.parameters defaults and the --values files. Callers use it to seed
// values from an earlier resolution (e.g. a committed scaffold record) so
// they take effect without re-prompting but still yield to explicit
// --values / --set input.
func ResolveLayered(t *Template, base map[string]any, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	return ResolveWith(t, ResolveOptions{Base: base, Files: files, Stdin: stdin, Sets: sets, Prompter: prompter})
}

// ResolveOptions is the full input to value resolution. The zero value is
// a bare resolve: schema defaults, then nothing else. Each field names one
// layer or instrument, in the order resolution applies them — Base under
// Files under Sets, Facts informing prefill and prompts, Prompter and
// Notes as the interactive and diagnostic surfaces.
type ResolveOptions struct {
	// Base sits between the schema defaults and the values files. Callers
	// seed it from an earlier resolution (e.g. a committed scaffold record)
	// so it takes effect without re-prompting but yields to explicit input.
	Base map[string]any

	// Facts is the workspace's declared wiring. It changes resolution in
	// two deliberate ways, both overridable with --set/--values:
	//

package template

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ScaffoldSchemaVersion is the newest scaffold.json schema this CLI
	// understands. Bump only for incompatible changes; additive fields do
	// not require a bump.
	ScaffoldSchemaVersion = 1

	// ScaffoldRelPath is where the scaffold record lives inside a project.
	ScaffoldRelPath = ".intropy/scaffold.json"

	// The manifest labels the CLI reads. Each has a legacy twin under the
	// domain the project used before intropy.io; LabelValue prefers the
	// current name and falls back, so a pinned older template release —
	// and the scaffold records already written from one — keep working.
	// Only the current names are ever written.
	//
	// TemplateRoleLabel declares what role a template's output plays in a
	// system. Its value is copied into the scaffold record so later
	// commands can tell support projects apart from system blocks.
	TemplateRoleLabel       = "intropy.io/template-role"
	LegacyTemplateRoleLabel = "intropy.dev/template-role"

	// RoleSharedLibrary marks a scaffolded project that exists to be
	// referenced by sibling components (e.g. shared models). System
	// assembly must not treat it as a block.
	RoleSharedLibrary = "shared-library"

	// RoleSystemHost marks the scaffolded host project of an integration
	// system. System assembly must not treat it as a block.
	RoleSystemHost = "system-host"

	// TemplateBlockKindLabel names the manifest label that declares which
	// Intropy block a template scaffolds (e.g. "extractor"). Its value is
	// copied into the scaffold record so `sys create` can assemble the
	// system declaration from what each scaffold recorded.
	TemplateBlockKindLabel       = "intropy.io/block-kind"
	LegacyTemplateBlockKindLabel = "intropy.dev/block-kind"

	// TemplateDataFlowLabel names the manifest label that declares the
	// block's data flow direction relative to the system ("in", "out",
	// or "both"). Recorded alongside the block kind.
	TemplateDataFlowLabel       = "intropy.io/data-flow"
	LegacyTemplateDataFlowLabel = "intropy.dev/data-flow"

	// TemplateMessageParamsLabel names the manifest label that declares
	// which parameters carry message wiring, as a comma-separated list of
	// parameter names. A template without it declares no message
	// parameters: --subscribe against it is a usage error (R4), and its
	// parameters get no message suggestions however they are named.
	TemplateMessageParamsLabel       = "intropy.io/message-params"
	LegacyTemplateMessageParamsLabel = "intropy.dev/message-params"

	// The BlockKind constants name the block kinds with a parse entry in
	// internal/system's blockParsers registry — the set `sys create`
	// assembles. Records carrying any other kind are skipped with a
	// warning.
	BlockKindExtractor     = "extractor"
	BlockKindLoader        = "loader"
	BlockKindTransactional = "transactional-integration"

	// Message direction values, derived from block kind. The mapping is
	// boundary-relative data-flow inverted: an extractor flows data in
	// from the external system and publishes messages, a loader flows out
	// and subscribes. MessageDirection is the one home of that flip.
	MessageDirectionPublish   = "publish"
	MessageDirectionSubscribe = "subscribe"
	MessageDirectionNone      = ""
