3	// The registry half: parse the export document into the shared Entry
4	// shape. All joins happen in memory against one GET /export — the registry
5	// declares filtering and per-entity reverse lookups out of scope, so there
6	// is nothing smaller to fetch.
7	
8	import (
9		"context"
10		"fmt"
11		"sort"
12		"strings"
13	
14		"github.com/integrio-intropy/intropy-cli/internal/xregistry"
15	)
16	
17	// registryEntries reads the export into entries, optionally narrowed to
18	// one group. Resolution failures that block wiring (an ambiguous or
19	// unreachable subscription channel) do not block listing: the table shows
20	// the channels it can see.
21	func registryEntries(ctx context.Context, client *xregistry.Client, group string) ([]Entry, error) {
22		doc, err := client.Export(ctx)
23		if err != nil {
24			return nil, err
25		}
26	
27		ids := make([]string, 0, len(doc.MessageGroups))
28		for id := range doc.MessageGroups {
29			ids = append(ids, id)
30		}
31		sort.Strings(ids)
32	
33		var out []Entry
34		for _, gid := range ids {
35			g := doc.MessageGroups[gid]
36			if group != "" && gid != group {
37				continue
38			}
39			for _, mid := range sortedMessageIDs(g) {
40				m := g.Messages[mid]
41				def := m.DefaultMessage()
42				if def == nil {
43					continue
44				}
45				e := Entry{
46					Message:  m.ID,
47					Source:   SourceRegistry,
48					Group:    gid,
49					Type:     envelopeType(def),
50					Envelope: def.Envelope,
51				}
52				e.Producers, e.Subscribers = groupEndpoints(doc, gid)
53				if def.DataSchemaXID != "" {
54					e.DataSchema = def.DataSchemaXID
55					e.DataSchemaName = schemaName(def.DataSchemaXID)
56					if xid, err := xregistry.DefaultSchemaVersionXID(doc, def.DataSchemaXID); err == nil {
57						e.DataSchemaURL = joinURL(client.BaseURL(), xid)
58					}
59				}
60				e.EnvelopeMeta = envelopeMetadata(def)
61				out = append(out, e)
62			}
63		}
64		return out, nil
65	}
66	
67	// registryEntry finds exactly one message by reference — bare message id
68	// or /messagegroups/<gid>/messages/<mid> xid — for `message show`.
69	func registryEntry(ctx context.Context, client *xregistry.Client, ref string) (*Entry, error) {
70		doc, err := client.Export(ctx)
71		if err != nil {
72			return nil, err
73		}
74		msg, group, err := xregistry.FindMessage(doc, ref)
75		if err != nil {
76			return nil, err
77		}
78		def := msg.DefaultMessage()
79		if def == nil {
80			return nil, fmt.Errorf("message %q in group %s carries no definition attributes", ref, group.ID)
81		}
82		e := &Entry{
83			Message:  msg.ID,
84			Source:   SourceRegistry,
85			Group:    group.ID,
86			Type:     envelopeType(def),
87			Envelope: def.Envelope,
88		}
89		e.Producers, e.Subscribers = groupEndpoints(doc, group.ID)
90		if def.DataSchemaXID != "" {
91			e.DataSchema = def.DataSchemaXID
92			e.DataSchemaName = schemaName(def.DataSchemaXID)
93			if xid, err := xregistry.DefaultSchemaVersionXID(doc, def.DataSchemaXID); err == nil {
94				e.DataSchemaURL = joinURL(client.BaseURL(), xid)
95			}
96		}
97		e.EnvelopeMeta = envelopeMetadata(def)
98		return e, nil
99	}
100	
101	func sortedMessageIDs(g xregistry.MessageGroup) []string {
102		ids := make([]string, 0, len(g.Messages))
103		for id := range g.Messages {
104			ids = append(ids, id)
105		}
106		sort.Strings(ids)
107		return ids
108	}
109	
110	// groupEndpoints splits the endpoints carrying one message group into the
111	// two ends of the message: who produces it and who consumes it.
112	//
113	// An endpoint's usage decides the side. "producer" is the producing end;
114	// "subscriber" and "consumer" are both spellings of the consuming one, and
115	// an endpoint declaring neither belongs to a role this CLI does not model,
116	// so it is reported on no side rather than guessed onto one.
117	//
118	// A malformed channel is skipped: listing must show what is resolvable, and
119	// assembly or --subscribe is the surface that reports the broken endpoint.
120	func groupEndpoints(doc *xregistry.Export, groupID string) (producers, subscribers []Endpoint) {
121		want := "/messagegroups/" + groupID
122		for _, e := range doc.Endpoints {
123			if !usageHas(e.MessageGroups, want) {
124				continue
125			}
126			channel := ""
127			if pubsub, topic, err := xregistry.SplitChannel(e.Channel); err == nil {
128				channel = pubsub + "/" + topic
129			}
130			ep := Endpoint{ID: e.ID, Name: e.Name, Channel: channel}
131			switch {
132			case usageHas(e.Usage, "producer"):
133				producers = append(producers, ep)
134			case usageHas(e.Usage, "subscriber"), usageHas(e.Usage, "consumer"):
135				subscribers = append(subscribers, ep)
136			}
137		}
138		sortEndpoints(producers)
139		sortEndpoints(subscribers)
140		return producers, subscribers
141	}
142	
143	// sortEndpoints orders by id, so a listing and a JSON document are stable
144	// across exports (the registry serves endpoints as a map).
145	func sortEndpoints(eps []Endpoint) {
146		sort.Slice(eps, func(i, j int) bool { return eps[i].ID < eps[j].ID })
147	}
148	
149	func usageHas(list []string, want string) bool {
150		for _, s := range list {
151			if s == want {
152				return true
153			}
154		}
155		return false
156	}
157	
158	// envelopeType extracts the CloudEvents type from the envelope metadata.
159	func envelopeType(def *xregistry.MessageVersion) string {
160		if attr, ok := def.EnvelopeMetadata["type"]; ok {
161			if s, ok := attr.Value.(string); ok {
162				return s
163			}
164		}
165		return ""
166	}
167	
168	// envelopeMetadata renders the envelope attributes sorted by name so the
169	// JSON document is stable across exports.
170	func envelopeMetadata(def *xregistry.MessageVersion) []EnvelopeAttribute {
171		names := make([]string, 0, len(def.EnvelopeMetadata))
172		for n := range def.EnvelopeMetadata {
173			names = append(names, n)
174		}
175		sort.Strings(names)
176		out := make([]EnvelopeAttribute, 0, len(names))
177		for _, n := range names {
178			a := def.EnvelopeMetadata[n]
179			kv := EnvelopeAttribute{Name: n, Required: a.Required}
180			if s, ok := a.Value.(string); ok {
181				kv.Value = s
182			} else if a.Value != nil {
183				kv.Value = fmt.Sprint(a.Value)
184			}
185			out = append(out, kv)
186		}
187		return out
188	}
189	
190	// schemaName renders the schema xid's resource tail for the table column.
191	func schemaName(xid string) string {
192		if i := strings.LastIndex(xid, "/schemas/"); i >= 0 {
193			rest := xid[i+len("/schemas/"):]
194			if j := strings.Index(rest, "/"); j >= 0 {
195				return rest[:j]
196			}
197			return rest
198		}
199		return xid
200	}
201	
202	// joinURL joins the registry base URL with a root-relative xid.
203	func joinURL(base, xid string) string {
204		return strings.TrimSuffix(base, "/") + xid
205	}
