13	// maxDependencyDepth bounds transitive dependency chains. Real chains are
14	// one level deep (component → shared library); the cap only exists to turn
15	// an authoring cycle that survives the visited-set check into a clear error.
16	const maxDependencyDepth = 5
17	
18	// DependencyResult reports what Create did about one declared dependency.
19	// Part of CreateResult's additive-only JSON contract.
20	type DependencyResult struct {
21		Template  string `json:"template"`
22		OutputDir string `json:"outputDir"`
23		Action    string `json:"action"` // "created" | "exists"
24	}
25	
26	// depContext carries the per-run state shared by every dependency render:
27	// the extracted templates repo (all templates of the resolved tag are
28	// already on disk) and a visited set so a diamond — two templates declaring
29	// the same sibling — renders it once.
30	type depContext struct {
31		repoRoot string
32		owner    string
33		repo     string
34		version  string
35		stderr   io.Writer
36		visited  map[string]bool
37	}
38	
39	// processDependencies renders every spec.dependencies entry of tmpl as a
40	// sibling of outputDir, recursively. An entry whose when condition evaluates
41	// false is skipped entirely; one whose target already carries a matching
42	// scaffold record is reused. It returns the records to embed in the parent's
43	// scaffold.json and the results for CreateResult.
44	func processDependencies(tmpl *Template, values map[string]any, outputDir string, dc *depContext, depth int) ([]DependencyRecord, []DependencyResult, error) {
45		if len(tmpl.Spec.Dependencies) == 0 {
46			return nil, nil, nil
47		}
48		if depth >= maxDependencyDepth {
49			return nil, nil, fmt.Errorf("dependency chain exceeds %d levels — check spec.dependencies for cycles", maxDependencyDepth)
50		}
51	
52		absOut, err := filepath.Abs(outputDir)
53		if err != nil {
54			return nil, nil, fmt.Errorf("absolute path for %s: %w", outputDir, err)
55		}
56		parentDir := filepath.Dir(absOut)
57	
58		var records []DependencyRecord
59		var results []DependencyResult
60		for _, dep := range tmpl.Spec.Dependencies {
61			if dep.When != "" {
62				rendered, err := renderExpr(dep.When, values)
63				if err != nil {
64					return nil, nil, fmt.Errorf("dependency %s: evaluate when: %w", dep.Template, err)
65				}
66				if !truthy(rendered) {
67					continue
68				}
69			}
70	
71			name, err := renderExpr(dep.Output, values)
72			if err != nil {
73				return nil, nil, fmt.Errorf("dependency %s: render output: %w", dep.Template, err)
74			}
75			if err := validateDependencyOutput(name); err != nil {
76				return nil, nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
77			}
78			depDir := filepath.Join(parentDir, name)
79			records = append(records, DependencyRecord{Template: dep.Template, Dir: path.Join("..", name)})
80	
81			if dc.visited[depDir] {
82				// Another dependency in this same run already claimed the
83				// directory; it was rendered (or skipped) there.
84				continue
85			}
86			dc.visited[depDir] = true
87	
88			depValues, err := renderDependencyValues(dep, values)
89			if err != nil {
90				return nil, nil, err
91			}
92	
93			existing, err := dependencyDirScaffold(depDir, dep.Template)
94			if err != nil {
95				return nil, nil, err
96			}
97			if existing != nil {
98				warnDependencyDrift(dc.stderr, name, dep, depValues, existing.Values)
99				fmt.Fprintf(dc.stderr, "dependency %s already scaffolded from %s — skipped\n", name, dep.Template)
100				results = append(results, DependencyResult{Template: dep.Template, OutputDir: depDir, Action: "exists"})
101				continue
102			}
103	
104			created, err := renderDependency(dep, name, depDir, depValues, dc, depth)
105			if err != nil {
106				return nil, nil, err
107			}
108			results = append(results, created...)
109		}
110		return records, results, nil
