113	// renderDependency scaffolds one dependency into depDir: resolve its values
114	// without prompting, render its skeleton, recurse into its own
115	// dependencies, and write its scaffold record. It returns the result for
116	// this dependency followed by any transitive ones.
117	func renderDependency(dep DependencySpec, name, depDir string, sets map[string]any, dc *depContext, depth int) ([]DependencyResult, error) {
118		depRoot := filepath.Join(dc.repoRoot, dep.Template)
119		depTmpl, err := LoadTemplate(filepath.Join(depRoot, templateManifestName))
120		if err != nil {
121			return nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
122		}
123	
124		// No prompter: a dependency render must never block on interactive
125		// input, since whether it runs at all depends on the target directory.
126		values, err := Resolve(depTmpl, nil, nil, sets, nil)
127		if err != nil {
128			return nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
129		}
130	
131		// --force never propagates to dependencies: overwriting a shared
132		// project that other components already reference is destructive at a
133		// distance. Regenerating one is an explicit `int create <template> --force`.
134		if err := renderCreateOutput(filepath.Join(depRoot, templateSkeletonDir), depTmpl, dep.Template, depDir, false, values); err != nil {
135			return nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
136		}
137	
138		subRecords, subResults, err := processDependencies(depTmpl, values, depDir, dc, depth+1)
139		if err != nil {
140			return nil, err
141		}
142	
143		if err := WriteScaffold(depDir, Scaffold{
144			SchemaVersion: ScaffoldSchemaVersion,
145			Template:      dep.Template,
146			Owner:         dc.owner,
147			Repo:          dc.repo,
148			Version:       dc.version,
149			Values:        values,
150			Role:          roleFromLabels(depTmpl.Metadata.Labels),
151			BlockKind:     blockKindFromLabels(depTmpl.Metadata.Labels),
152			DataFlow:      dataFlowFromLabels(depTmpl.Metadata.Labels),
153			DependsOn:     subRecords,
154		}); err != nil {
155			return nil, fmt.Errorf("dependency %s: %w", dep.Template, err)
156		}
157	
158		fmt.Fprintf(dc.stderr, "created dependency %s from template %s\n", name, dep.Template)
159		own := DependencyResult{Template: dep.Template, OutputDir: depDir, Action: "created"}
160		return append([]DependencyResult{own}, subResults...), nil
161	}
162	
163	// renderDependencyValues renders the dependency's values map against the
164	// parent's resolved values. Every rendered value is a string; Resolve's
165	// schema-type coercion turns them into booleans/integers where the
166	// dependency's parameters call for it.
167	func renderDependencyValues(dep DependencySpec, parentValues map[string]any) (map[string]any, error) {
168		out := make(map[string]any, len(dep.Values))
169		for k, expr := range dep.Values {
170			rendered, err := renderExpr(expr, parentValues)
171			if err != nil {
172				return nil, fmt.Errorf("dependency %s: render values.%s: %w", dep.Template, k, err)
173			}
174			out[k] = rendered
175		}
176		return out, nil
177	}
