179	// dependencyDirScaffold classifies the dependency target directory. It
180	// returns the existing scaffold record when the directory is already managed
181	// by the same template (the skip case), nil when the directory is missing or
182	// empty (the render case), and an error for anything else — a foreign
183	// template's project or an unmanaged non-empty directory is never touched.
184	func dependencyDirScaffold(dir, wantTemplate string) (*Scaffold, error) {
185		info, err := os.Stat(dir)
186		switch {
187		case errors.Is(err, os.ErrNotExist):
188			return nil, nil
189		case err != nil:
190			return nil, err
191		case !info.IsDir():
192			return nil, fmt.Errorf("dependency target %s exists and is not a directory", dir)
193		}
194	
195		scaffoldPath := filepath.Join(dir, filepath.FromSlash(ScaffoldRelPath))
196		if _, err := os.Stat(scaffoldPath); err == nil {
197			s, err := LoadScaffold(scaffoldPath)
198			if err != nil {
199				return nil, err
200			}
201			if s.Template != wantTemplate {
202				return nil, fmt.Errorf("dependency target %s is already scaffolded from template %q, expected %q", dir, s.Template, wantTemplate)
203			}
204			return s, nil
205		} else if !errors.Is(err, os.ErrNotExist) {
206			return nil, err
207		}
208	
209		entries, err := os.ReadDir(dir)
210		if err != nil {
211			return nil, err
212		}
213		if len(entries) > 0 {
214			return nil, fmt.Errorf("dependency target %s is not empty and has no %s — refusing to overwrite an unmanaged directory", dir, ScaffoldRelPath)
215		}
216		return nil, nil
217	}
