219	// warnDependencyDrift compares the values this render would have passed to
220	// the dependency with what its scaffold record holds, and warns on
221	// mismatches. Drift is informational: the existing project wins.
222	func warnDependencyDrift(stderr io.Writer, name string, dep DependencySpec, want map[string]any, recorded map[string]any) {
223		var drifted []string
224		for k, v := range want {
225			rec, ok := recorded[k]
226			if !ok {
227				continue
228			}
229			if fmt.Sprint(rec) != fmt.Sprint(v) {
230				drifted = append(drifted, fmt.Sprintf("%s (recorded %v, this component derived %v)", k, rec, v))
231			}
232		}
233		if len(drifted) > 0 {
234			fmt.Fprintf(stderr, "warning: dependency %s (%s) was scaffolded with different values: %s\n", name, dep.Template, strings.Join(drifted, "; "))
235		}
236	}
