238	// validateDependencyOutput rejects rendered output names that are not a
239	// plain single path segment, so a dependency can only ever land as a direct
240	// sibling of the component.
241	func validateDependencyOutput(name string) error {
242		if name == "" {
243			return errors.New("output rendered to an empty string")
244		}
245		if name != filepath.Clean(name) || name == "." || name == ".." ||
246			strings.HasPrefix(name, ".") || strings.ContainsAny(name, `/\`) || filepath.IsAbs(name) {
247			return fmt.Errorf("output %q must be a single path segment (no separators, no leading dot)", name)
248		}
249		return nil
250	}
