119	// RenderUpdate is RenderFiltered with per-file outcomes instead of
120	// unconditional overwrite: rendering produces bytes first, then each file is
121	// classified against the destination — absent is created, identical to the
122	// merged render is unchanged, identical to the baseline render is updated,
123	// and anything else is a conflict (or, with Force, an update). Nothing is
124	// written on dry-run, and nothing is written past the first conflict without
125	// Force, so a caller can refuse a divergent tree without leaving a partial
126	// render behind. The destination is not subjected to the create flow's
127	// non-empty refusal: updating means rendering into a directory that already
128	// holds a project.
129	func RenderUpdate(srcDir, destDir string, values map[string]any, rules []FileRule, opts RenderUpdateOptions) ([]FileOutcome, error) {
130		filter := newSkeletonFilter(rules, values)
131		var outcomes []FileOutcome
132		err := filepath.WalkDir(srcDir, func(path string, d fs.DirEntry, err error) error {
133			if err != nil {
134				return err
135			}
136			rel, err := filepath.Rel(srcDir, path)
