// Package contract turns a message's payload schema into the model a
// template renders contract types from.
//
// It deliberately knows nothing about C#. The registry serves JSON Schema, so
// this package speaks JSON Schema: a property carries its schema type, its
// format, whether it is required, and whether it is an array. Which .NET type
// a `string` with `format: date-time` becomes, how nullability is spelled,
// and whether a name needs escaping are the template library's decisions —
// customers fork the template library, never this CLI, so every choice they
// might want to change has to live there.
//
// The seam is Payload: the value the CLI injects under the `messages`
// reserved key, from which a skeleton renders whatever it likes.
package contract

// Model is one message's payload types: the message identity a template
// labels the file with, the schema references that pin it, and the records
// the schema described.
type Model struct {
	Message       string
	Type          string
	Contract      string
	DataSchema    string
	DataSchemaURL string

	// SchemaFile is the committed document's path relative to the contracts
	// project root — the render input, so a fork of the template library can
	// re-render without reaching the registry.
	SchemaFile string

	Records []Record
}

// Record is one type the schema described: the root object, or one entry of
// its $defs that something references.
type Record struct {
	Name string
	Doc  string

	// Properties are in document order. A positional record's parameter list
	// is its public API, so the order a reader sees in the schema is the
	// order the generated type gets; nothing re-sorts it.
	Properties []Property
}

// Property is one member of a record, described the way the schema described
// it. Ref names the record a nested object resolves to — for an array, the
// record of its items.
type Property struct {
	Name       string
	JSONName   string
	SchemaType string
	Format     string
	Required   bool
	Array      bool
	Ref        string
	Enum       []string
	Doc        string
}

// Payload renders models as the `messages` reserved value: a list of maps
// with lowercase keys, matching the system-host payload's shape
// (internal/system/payload.go).
//
// Every key is always present, empty ones included — unlike that payload,
// which omits empties. A skeleton mapping schema types to language types
// reads `.format` and `.ref` on every property it touches, and rendering
// runs with missingkey=error, so omitting a key would force a hasKey guard
// around every branch of the mapping.
func Payload(models []Model) []any {
	out := make([]any, len(models))
	for i, m := range models {
		records := make([]any, len(m.Records))
		for j, r := range m.Records {
			props := make([]any, len(r.Properties))
			for k, p := range r.Properties {
				enum := make([]any, len(p.Enum))
				for l, v := range p.Enum {
					enum[l] = v
				}
				props[k] = map[string]any{
					"name":       p.Name,
					"jsonName":   p.JSONName,
					"schemaType": p.SchemaType,
					"format":     p.Format,
					"required":   p.Required,
					"array":      p.Array,
					"ref":        p.Ref,
					"enum":       enum,
					"doc":        p.Doc,
				}
			}
			records[j] = map[string]any{
				"name":       r.Name,
				"doc":        r.Doc,
				"properties": props,
			}
		}
		out[i] = map[string]any{
			"message":       m.Message,
			"type":          m.Type,
			"contract":      m.Contract,
			"dataschema":    m.DataSchema,
			"dataschemaurl": m.DataSchemaURL,
			"schemaFile":    m.SchemaFile,
			"records":       records,
		}
	}
	return out
}
EOF
