package contract

import (
	"fmt"
	"strings"
	"unicode"
)

// identifier suggests a type or member name for a schema name. It is a
// suggestion only: the template owns the final identifier, including any
// escaping the target language needs for a keyword collision.
//
// The transform splits on anything that cannot appear in an identifier and
// upper-cases each part's first rune, leaving the rest alone — so "exportId"
// becomes "ExportId", "unit-conversion" becomes "UnitConversion", and the
// registry's own "gTIN" becomes "GTIN" rather than being re-cased into
// something that no longer round-trips.
func identifier(name string) (string, error) {
	var b strings.Builder
	upper := true
	for _, r := range name {
		switch {
		case unicode.IsLetter(r) || unicode.IsDigit(r):
			if upper {
				b.WriteRune(unicode.ToUpper(r))
				upper = false
			} else {
				b.WriteRune(r)
			}
		case r == '_':
			// Kept: it is identifier-legal everywhere, and dropping it would
			// collide "id_" with "id".
			b.WriteRune(r)
			upper = true
		default:
			upper = true
		}
	}
	out := b.String()
	if out == "" || out == "_" {
		return "", fmt.Errorf("name %q has no identifier characters", name)
	}
	// A leading digit is legal in no target language this feeds.
	if r := []rune(out)[0]; unicode.IsDigit(r) {
		out = "_" + out
	}
	return out, nil
}

// uniqueIdentifiers suggests a name for each schema name in order, failing on
// a collision rather than emitting two members that cannot coexist. The error
// names both sources, because the fix is a schema change and the author needs
// to know which two properties to look at.
func uniqueIdentifiers(names []string) ([]string, error) {
	out := make([]string, len(names))
	seen := make(map[string]string, len(names))
	for i, n := range names {
		id, err := identifier(n)
		if err != nil {
			return nil, err
		}
		if prev, dup := seen[id]; dup {
			return nil, fmt.Errorf("properties %q and %q both name %q", prev, n, id)
		}
		seen[id] = n
		out[i] = id
	}
	return out, nil
}
EOF
