package contract

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

// FormatJSONSchema is the one schema format the registry serves. A consumer
// checks the message's declared format against it before parsing: the
// registry narrows `format` to this single value, and a document in anything
// else is not a document this package understands.
const FormatJSONSchema = "JsonSchema/draft/2020-12"

// defsPrefix is the only $ref target shape this package resolves. A ref to
// another document would name a schema the pin does not cover, so it is a
// failure rather than a silent skip.
const defsPrefix = "#/$defs/"

// Options steers Parse.
type Options struct {
	// RootName names the root record. Empty derives it from the schema's
	// title, then from FallbackName.
	RootName string

	// FallbackName is used when RootName is empty and the schema carries no
	// title.
	FallbackName string
}

// Parse reads one JSON Schema document into the records a template renders.
//
// Only the constructs the registry's schemas use are understood: an object
// with properties, arrays, $defs referenced through a local $ref, enums, and
// the string formats. Anything else fails naming what it found — a
// half-understood schema would produce a type that silently does not match
// the messages on the wire.
func Parse(doc []byte, opts Options) ([]Record, error) {
	var root node
	if err := json.Unmarshal(doc, &root); err != nil {
		return nil, fmt.Errorf("parse schema document: %w", err)
	}

	name := opts.RootName
	if name == "" && root.Title != "" {
		id, err := identifier(root.Title)
		if err != nil {
			return nil, fmt.Errorf("schema title: %w", err)
		}
		name = id
	}
	if name == "" {
		name = opts.FallbackName
	}
	if name == "" {
		return nil, fmt.Errorf("schema has no title and no name was supplied")
	}

	p := &parser{defs: root.Defs, byName: map[string]bool{}}
	if err := p.record(name, &root); err != nil {
		return nil, err
	}
	return p.records, nil
}

// parser walks one document. Records are collected root first, then in the
// order refs are encountered, so a schema always yields the same list.
type parser struct {
	defs    map[string]json.RawMessage
	records []Record
	byName  map[string]bool
	// pending guards a $ref cycle: a record being built is already claimed.
	pending map[string]bool
}

// record appends the record for one object schema, resolving nested types as
// it goes. The name is already an identifier suggestion.
func (p *parser) record(name string, n *node) error {
	if p.byName[name] || p.pending[name] {
		return nil
	}
	if p.pending == nil {
		p.pending = map[string]bool{}
	}
	p.pending[name] = true

	req := make(map[string]bool, len(n.Required))
	for _, r := range n.Required {
		req[r] = true
	}

	ids, err := uniqueIdentifiers(n.Properties.keys)
	if err != nil {
		return fmt.Errorf("record %s: %w", name, err)
	}

	rec := Record{Name: name, Doc: n.Description, Properties: make([]Property, 0, len(ids))}
	for i, key := range n.Properties.keys {
		var pn node
		if err := json.Unmarshal(n.Properties.vals[key], &pn); err != nil {
			return fmt.Errorf("record %s: property %s: %w", name, key, err)
		}
		prop, err := p.property(name, key, ids[i], &pn, req[key])
		if err != nil {
			return fmt.Errorf("record %s: %w", name, err)
		}
		rec.Properties = append(rec.Properties, prop)
	}

	delete(p.pending, name)
	p.byName[name] = true
	p.records = append(p.records, rec)
	return nil
}

// property describes one member and, when it carries a nested object,
// ensures that object's record exists.
func (p *parser) property(parent, key, id string, n *node, required bool) (Property, error) {
	prop := Property{Name: id, JSONName: key, Required: required, Doc: n.Description}

	// An explicit null in the type union means optional however `required`
	// reads: a schema saying so is more specific than the required list.
	kind, nullable, err := n.kind()
	if err != nil {
		return prop, fmt.Errorf("property %s: %w", key, err)
	}
	if nullable {
		prop.Required = false
	}

	item := n
	if kind == "array" {
		if n.Items == nil {
			return prop, fmt.Errorf("property %s: array has no items schema", key)
		}
		prop.Array = true
		item = n.Items
		if kind, _, err = item.kind(); err != nil {
			return prop, fmt.Errorf("property %s: items: %w", key, err)
		}
		if kind == "array" {
			return prop, fmt.Errorf("property %s: nested arrays are not supported", key)
		}
	}

	prop.SchemaType = kind
	prop.Format = item.Format
	prop.Enum = stringEnum(item.Enum)

	switch {
	case item.Ref != "":
		ref, err := p.resolveRef(item.Ref)
		if err != nil {
			return prop, fmt.Errorf("property %s: %w", key, err)
		}
		prop.Ref = ref
		prop.SchemaType = "object"
	case kind == "object":
		// An inline object: no $defs entry to name it, so it is named for the
		// property, disambiguated by its parent when that name is taken.
		name := id
		if p.byName[name] || p.pending[name] {
			name = parent + id
		}
		if p.byName[name] || p.pending[name] {
			return prop, fmt.Errorf("property %s: cannot name its inline object type; move it to $defs", key)
		}
		if err := p.record(name, item); err != nil {
			return prop, err
		}
		prop.Ref = name
	}
	return prop, nil
}

// resolveRef resolves a local $defs reference and ensures its record exists.
func (p *parser) resolveRef(ref string) (string, error) {
	defName, ok := strings.CutPrefix(ref, defsPrefix)
	if !ok || defName == "" {
		return "", fmt.Errorf("$ref %q is not %s<name>; a schema outside this document is not covered by the pin", ref, defsPrefix)
	}
	raw, ok := p.defs[defName]
	if !ok {
		return "", fmt.Errorf("$ref %q names no entry in $defs", ref)
	}
	id, err := identifier(defName)
	if err != nil {
		return "", fmt.Errorf("$defs entry %q: %w", defName, err)
	}
	var n node
	if err := json.Unmarshal(raw, &n); err != nil {
		return "", fmt.Errorf("$defs entry %q: %w", defName, err)
	}
	if err := p.record(id, &n); err != nil {
		return "", err
	}
	return id, nil
}

// node is the subset of a schema this package reads.
type node struct {
	Title       string                     `json:"title"`
	Description string                     `json:"description"`
	Type        json.RawMessage            `json:"type"`
	Format      string                     `json:"format"`
	Required    []string                   `json:"required"`
	Properties  orderedProps               `json:"properties"`
	Items       *node                      `json:"items"`
	Ref         string                     `json:"$ref"`
	Enum        []any                      `json:"enum"`
	Defs        map[string]json.RawMessage `json:"$defs"`
}

// kind reads the schema type, which may be a bare string or a union. A union
// carrying "null" describes an optional value; any other union is ambiguous
// about which type to generate, so it fails rather than picking one.
func (n *node) kind() (kind string, nullable bool, err error) {
	if len(n.Type) == 0 {
		// A node with only a $ref carries no type of its own.
		if n.Ref != "" {
			return "object", false, nil
		}
		return "", false, nil
	}
	var one string
	if err := json.Unmarshal(n.Type, &one); err == nil {
		if one == "null" {
			return "", true, nil
		}
		return one, false, nil
	}
	var many []string
	if err := json.Unmarshal(n.Type, &many); err != nil {
		return "", false, fmt.Errorf("type is neither a string nor a list of strings")
	}
	for _, t := range many {
		if t == "null" {
			nullable = true
			continue
		}
		if kind != "" {
			return "", false, fmt.Errorf("type union %v has no single type to generate", many)
		}
		kind = t
	}
	if kind == "" {
		return "", nullable, fmt.Errorf("type %v names no type to generate", many)
	}
	return kind, nullable, nil
}

// stringEnum keeps an enum only when every value is a string. A mixed or
// numeric enum still generates as its base type; nothing is lost that the
// schema type does not already say.
func stringEnum(values []any) []string {
	if len(values) == 0 {
		return nil
	}
	out := make([]string, 0, len(values))
	for _, v := range values {
		s, ok := v.(string)
		if !ok {
			return nil
		}
		out = append(out, s)
	}
	return out
}

// orderedProps decodes a properties object while keeping its key order. A
// generated positional record's parameter order is its public API, so it
// follows the document rather than Go's map iteration.
type orderedProps struct {
	keys []string
	vals map[string]json.RawMessage
}

func (o *orderedProps) UnmarshalJSON(b []byte) error {
	o.vals = map[string]json.RawMessage{}
	dec := json.NewDecoder(bytes.NewReader(b))
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if d, ok := tok.(json.Delim); !ok || d != '{' {
		return fmt.Errorf("properties is not an object")
	}
	for dec.More() {
		tok, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := tok.(string)
		if !ok {
			return fmt.Errorf("properties key is not a string")
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return err
		}
		if _, dup := o.vals[key]; !dup {
			o.keys = append(o.keys, key)
		}
		o.vals[key] = raw
	}
	return nil
}
EOF
