package contract

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The fixtures are the registry's own seed documents, copied verbatim. They
// are the contract this parser has to meet, so a change to them upstream
// should land here as a copy rather than as a hand-edited approximation.
func readFixture(t *testing.T, name string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read fixture: %v", err)
	}
	return b
}

func recordByName(t *testing.T, records []Record, name string) Record {
	t.Helper()
	for _, r := range records {
		if r.Name == name {
			return r
		}
	}
	t.Fatalf("no record %q in %v", name, recordNames(records))
	return Record{}
}

func recordNames(records []Record) []string {
	var out []string
	for _, r := range records {
		out = append(out, r.Name)
	}
	return out
}

func propByJSONName(t *testing.T, r Record, jsonName string) Property {
	t.Helper()
	for _, p := range r.Properties {
		if p.JSONName == jsonName {
			return p
		}
	}
	t.Fatalf("record %s has no property %q", r.Name, jsonName)
	return Property{}
}

