func TestParseRejects(t *testing.T) {
	tests := []struct {
		name string
		doc  string
		want string
	}{
		{
			name: "external ref",
			doc:  `{"title":"X","type":"object","properties":{"a":{"$ref":"https://example.com/other.json"}}}`,
			want: "not covered by the pin",
		},
		{
			name: "ref to a missing def",
			doc:  `{"title":"X","type":"object","properties":{"a":{"$ref":"#/$defs/Nope"}}}`,
			want: "names no entry in $defs",
		},
		{
			name: "nested arrays",
			doc:  `{"title":"X","type":"object","properties":{"a":{"type":"array","items":{"type":"array","items":{"type":"string"}}}}}`,
			want: "nested arrays are not supported",
		},
		{
			name: "array without items",
			doc:  `{"title":"X","type":"object","properties":{"a":{"type":"array"}}}`,
			want: "array has no items schema",
		},
		{
			name: "colliding property names",
			doc:  `{"title":"X","type":"object","properties":{"unit-price":{"type":"string"},"unitPrice":{"type":"string"}}}`,
			want: `both name "UnitPrice"`,
		},
		{
			name: "ambiguous type union",
			doc:  `{"title":"X","type":"object","properties":{"a":{"type":["string","integer"]}}}`,
			want: "no single type to generate",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := Parse([]byte(tt.doc), Options{})
			if err == nil {
				t.Fatalf("Parse succeeded, want an error mentioning %q", tt.want)
			}
			if !strings.Contains(err.Error(), tt.want) {
