	}
	for _, tt := range tests {
		got, err := identifier(tt.in)
		if err != nil {
			t.Errorf("identifier(%q): %v", tt.in, err)
			continue
		}
		if got != tt.want {
			t.Errorf("identifier(%q) = %q, want %q", tt.in, got, tt.want)
