	}
	if _, err := identifier("---"); err == nil {
		t.Error("a name with no identifier characters must fail")
	}
}

func jsonNames(r Record) []string {
	var out []string
	for _, p := range r.Properties {
		out = append(out, p.JSONName)
	}
	return out
}

func equal(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
