package contract

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path"
	"path/filepath"
	"sort"
)

const (
	// IndexSchemaVersion is the newest messages.json this CLI understands.
	// Bump only for incompatible changes; additive fields do not require it.
	IndexSchemaVersion = 1

	// IndexRelPath is where the index lives inside a contracts project,
	// beside the scaffold record the dependency render writes.
	IndexRelPath = ".intropy/messages.json"

	// SchemaDirName holds the committed schema documents, relative to the
	// contracts project root.
	SchemaDirName = "schemas"
)

// Index is a contracts project's record of the messages it carries types
// for. It holds references, never a parsed model: the committed schema
// documents are the one source of truth for shape, and the model is derived
// from them, so the two cannot disagree.
type Index struct {
	SchemaVersion int     `json:"schemaVersion"`
	Messages      []Entry `json:"messages"`
}

// Entry is one message's provenance: what it is, which type was generated
// for it, and which pinned schema document that came from.
type Entry struct {
	Message       string `json:"message"`
	Type          string `json:"type,omitempty"`
	Contract      string `json:"contract"`
	DataSchema    string `json:"dataschema,omitempty"`
	DataSchemaURL string `json:"dataschemaurl,omitempty"`
	SchemaFile    string `json:"schemaFile"`
}

// LoadIndex reads a contracts project's index. A project without one is not
// an error — every project starts without it — so the zero index comes back
// ready to merge into.
func LoadIndex(projectDir string) (*Index, error) {
	p := filepath.Join(projectDir, filepath.FromSlash(IndexRelPath))
	b, err := os.ReadFile(p)
	if errors.Is(err, os.ErrNotExist) {
		return &Index{SchemaVersion: IndexSchemaVersion}, nil
	}
	if err != nil {
		return nil, err
	}
	var idx Index
	if err := json.Unmarshal(b, &idx); err != nil {
		return nil, fmt.Errorf("parse %s: %w", p, err)
	}
	if idx.SchemaVersion > IndexSchemaVersion {
		return nil, fmt.Errorf("%s was written by a newer intropy (schema version %d, this CLI understands %d)", p, idx.SchemaVersion, IndexSchemaVersion)
	}
	return &idx, nil
}

// Merge adds or replaces one message's entry, keeping the list sorted by
// message id so the file is stable across runs and a diff shows only what
// the run changed.
func (idx *Index) Merge(e Entry) {
	idx.SchemaVersion = IndexSchemaVersion
	for i := range idx.Messages {
		if idx.Messages[i].Message == e.Message {
			idx.Messages[i] = e
			return
		}
	}
	idx.Messages = append(idx.Messages, e)
	sort.Slice(idx.Messages, func(i, j int) bool { return idx.Messages[i].Message < idx.Messages[j].Message })
}

// Write persists the index into a contracts project.
func (idx *Index) Write(projectDir string) error {
	if idx.SchemaVersion == 0 {
		idx.SchemaVersion = IndexSchemaVersion
	}
	b, err := json.MarshalIndent(idx, "", "  ")
	if err != nil {
		return err
	}
	b = append(b, '\n')
	return writeFile(filepath.Join(projectDir, filepath.FromSlash(IndexRelPath)), b)
}

// SchemaFileName names the committed document for one message and pinned
// version. The version is in the name because the pin is what makes the
// document immutable: re-pinning a message writes a new file rather than
// silently changing the shape behind an existing one.
func SchemaFileName(message, versionID string) string {
	if versionID == "" {
		return path.Join(SchemaDirName, message+".json")
	}
	return path.Join(SchemaDirName, message+".v"+versionID+".json")
}

// WriteSchemaDocument commits one schema document under the contracts
// project's schemas/ directory. The bytes are written exactly as the registry
// served them: a reformatted document would no longer be the thing the pin
// names.
func WriteSchemaDocument(projectDir, relPath string, doc []byte) error {
	return writeFile(filepath.Join(projectDir, filepath.FromSlash(relPath)), doc)
}

// LoadModels rebuilds the render model for every message a contracts project
// carries, by re-parsing the committed documents.
//
// This is what makes a re-render offline: adding a second message, or picking
// up a template library whose record style changed, needs the schemas that
// are already on disk and nothing from the registry.
func LoadModels(projectDir string) ([]Model, error) {
	idx, err := LoadIndex(projectDir)
	if err != nil {
		return nil, err
	}
	models := make([]Model, 0, len(idx.Messages))
	for _, e := range idx.Messages {
		doc, err := os.ReadFile(filepath.Join(projectDir, filepath.FromSlash(e.SchemaFile)))
		if err != nil {
			return nil, fmt.Errorf("message %s: %w", e.Message, err)
		}
		records, err := Parse(doc, Options{RootName: e.Contract})
		if err != nil {
			return nil, fmt.Errorf("message %s: %w", e.Message, err)
		}
		models = append(models, Model{
			Message:       e.Message,
			Type:          e.Type,
			Contract:      e.Contract,
			DataSchema:    e.DataSchema,
			DataSchemaURL: e.DataSchemaURL,
			SchemaFile:    e.SchemaFile,
			Records:       records,
		})
	}
	return models, nil
}

// writeFile writes through a temp file and a rename, so a reader never sees a
// half-written document.
//
// internal/template has the same primitive, deliberately not borrowed:
// internal/template imports this package to build its render model, so
// depending back on it would be an import cycle.
func writeFile(dest string, b []byte) error {
	if err := os.MkdirAll(filepath.Dir(dest), 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(dest), ".tmp-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := io.Copy(tmp, bytesReader(b)); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), 0o644); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), dest)
}
