package contract

import (
	"fmt"
	"strings"
)

// Source is one resolved message's schema facts. It mirrors what a registry
// resolution produced without naming the registry's types, so this package
// stays independent of the client and easy to drive from a test.
type Source struct {
	Message       string
	Type          string
	Contract      string
	DataSchema    string
	DataSchemaURL string
	SchemaFormat  string
	Version       string
	Document      []byte
}

// Supported reports whether a message's declared schema format is one this
// package can parse. The registry narrows the format to a single value, so a
// false here means the registry widened and this package has not caught up —
// a diagnostic for the caller, never a reason to fail a scaffold.
func Supported(format string) bool {
	// An empty format is the registry's own default for a JSON Schema
	// document, so it is read as one rather than refused.
	return format == "" || format == FormatJSONSchema
}

// Build turns one resolved message into its render model. It parses only; the
// project on disk is untouched, because the model has to exist before the
// render that creates the project.
func Build(src Source) (Model, error) {
	if len(src.Document) == 0 {
		return Model{}, fmt.Errorf("message %s: no schema document to generate from", src.Message)
	}
	records, err := Parse(src.Document, Options{
		RootName:     src.Contract,
		FallbackName: fallbackName(src.DataSchema),
	})
	if err != nil {
		return Model{}, fmt.Errorf("message %s: %w", src.Message, err)
	}
	contract := src.Contract
	if contract == "" && len(records) > 0 {
		contract = records[0].Name
	}
	return Model{
		Message:       src.Message,
		Type:          src.Type,
		Contract:      contract,
		DataSchema:    src.DataSchema,
		DataSchemaURL: src.DataSchemaURL,
		SchemaFile:    SchemaFileName(src.Message, src.Version),
		Records:       records,
	}, nil
}

// Commit writes the schema document and the index entry into a contracts
// project. It runs after the render, not before: the dependency render
// refuses a target directory that holds files but no scaffold record, so
// seeding the project with a document first would make it look unmanaged.
func Commit(projectDir string, m Model) error {
	if err := WriteSchemaDocument(projectDir, m.SchemaFile, m.document); err != nil {
		return fmt.Errorf("write %s: %w", m.SchemaFile, err)
	}
	idx, err := LoadIndex(projectDir)
	if err != nil {
		return err
	}
	idx.Merge(Entry{
		Message:       m.Message,
		Type:          m.Type,
		Contract:      m.Contract,
		DataSchema:    m.DataSchema,
		DataSchemaURL: m.DataSchemaURL,
		SchemaFile:    m.SchemaFile,
	})
	return idx.Write(projectDir)
}

// Merge places one model into the set a project already carries, replacing
// the entry for the same message. The result is what a render sees, and what
// the previous set was is the baseline a re-render compares against.
func Merge(existing []Model, m Model) []Model {
	out := make([]Model, 0, len(existing)+1)
	replaced := false
	for _, e := range existing {
		if e.Message == m.Message {
			out = append(out, m)
			replaced = true
			continue
		}
		out = append(out, e)
	}
	if !replaced {
		out = append(out, m)
	}
	sortModels(out)
	return out
}

// fallbackName derives a last-resort record name from a schema xid, for a
// document with no title that the caller did not name either.
func fallbackName(dataschema string) string {
	tail := dataschema
	if i := strings.LastIndex(tail, "/"); i >= 0 {
		tail = tail[i+1:]
	}
	if tail == "" {
		return ""
	}
	id, err := identifier(tail)
	if err != nil {
		return ""
	}
	return id
}
