	if got := []string{idx.Messages[0].Message, idx.Messages[1].Message}; got[0] != "a.msg" || got[1] != "b.msg" {
		t.Fatalf("order = %v, want sorted by message id", got)
	}

	idx.Merge(Entry{Message: "a.msg", Contract: "A", SchemaFile: "schemas/a.v2.json"})
	if len(idx.Messages) != 2 {
		t.Fatalf("messages = %d, want the re-pinned entry to replace, not append", len(idx.Messages))
	}
	if got := idx.Messages[0].SchemaFile; got != "schemas/a.v2.json" {
		t.Errorf("schemaFile = %q, want the new pin", got)
	}
}

func TestIndexRoundTrip(t *testing.T) {
	dir := t.TempDir()
	idx, err := LoadIndex(dir)
	if err != nil {
		t.Fatalf("LoadIndex on a project without one: %v", err)
	}
	if len(idx.Messages) != 0 {
		t.Fatal("a project with no index starts empty")
	}
	idx.Merge(Entry{Message: "m", Contract: "C", SchemaFile: "schemas/m.v1.json"})
	if err := idx.Write(dir); err != nil {
		t.Fatalf("Write: %v", err)
	}

	back, err := LoadIndex(dir)
	if err != nil {
		t.Fatalf("LoadIndex: %v", err)
	}
	if len(back.Messages) != 1 || back.Messages[0].Contract != "C" {
		t.Errorf("read back %+v", back.Messages)
	}
	if back.SchemaVersion != IndexSchemaVersion {
		t.Errorf("schemaVersion = %d, want %d", back.SchemaVersion, IndexSchemaVersion)
	}
}

func TestLoadIndexRefusesANewerSchemaVersion(t *testing.T) {
	dir := t.TempDir()
	if err := os.MkdirAll(filepath.Join(dir, ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	body, _ := json.Marshal(Index{SchemaVersion: IndexSchemaVersion + 1})
	if err := os.WriteFile(filepath.Join(dir, filepath.FromSlash(IndexRelPath)), body, 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := LoadIndex(dir); err == nil {
		t.Error("an index from a newer CLI must be refused, not half-read")
	}
}

func TestSchemaFileName(t *testing.T) {
	if got, want := SchemaFileName("io.intropy.maxbo.product.export", "2"), "schemas/io.intropy.maxbo.product.export.v2.json"; got != want {
		t.Errorf("SchemaFileName = %q, want %q", got, want)
	}
	if got, want := SchemaFileName("m", ""), "schemas/m.json"; got != want {
		t.Errorf("unversioned SchemaFileName = %q, want %q", got, want)
	}
}

func TestBuildCommitAndLoadModels(t *testing.T) {
	dir := t.TempDir()
	doc := readFixture(t, "product-export.v2.json")
	src := Source{
		Message:       "io.intropy.maxbo.product.export",
		Type:          "io.intropy.maxbo.product.export",
		Contract:      "ExportEvent",
		DataSchema:    "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1",
		DataSchemaURL: "https://registry.example/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1/versions/2",
		Version:       "2",
		Document:      doc,
	}
	m, err := Build(src)
	if err != nil {
		t.Fatalf("Build: %v", err)
	}
	if m.SchemaFile != "schemas/io.intropy.maxbo.product.export.v2.json" {
		t.Errorf("SchemaFile = %q", m.SchemaFile)
	}
	if err := Commit(dir, m); err != nil {
		t.Fatalf("Commit: %v", err)
	}

	// The document is committed exactly as served: the pin names these bytes.
	onDisk, err := os.ReadFile(filepath.Join(dir, filepath.FromSlash(m.SchemaFile)))
	if err != nil {
		t.Fatalf("read committed document: %v", err)
	}
	if string(onDisk) != string(doc) {
		t.Error("committed document differs from what the registry served")
	}

	// And the model rebuilds from disk alone — the offline re-render path.
	models, err := LoadModels(dir)
	if err != nil {
		t.Fatalf("LoadModels: %v", err)
	}
	if len(models) != 1 || models[0].Contract != "ExportEvent" {
		t.Fatalf("models = %+v", models)
	}
	if len(models[0].Records) != 2 {
		t.Errorf("records = %v, want the root and its $defs entry", recordNames(models[0].Records))
	}
	if err := Commit(dir, models[0]); err == nil {
		t.Error("a model rebuilt from disk carries no document and must refuse to re-commit")
	}
}

func TestMergeModels(t *testing.T) {
