func TestPayloadAlwaysCarriesEveryKey(t *testing.T) {
	m := Model{Message: "m", Contract: "C", Records: []Record{{
		Name:       "C",
		Properties: []Property{{Name: "A", JSONName: "a", SchemaType: "string"}},
	}}}
