func (o *CreateOptions) applyDefaults() {

// RefsOptions selects the candidate pool offered as prompt suggestions.
type RefsOptions struct {
	RegistryURL string
	UserAgent   string
}

// Subscribe resolves a message reference into the subscribe block a
// consuming component's scaffold record carries: the message, the channel
// its producer publishes on, the schema pinned to its default version, and
// the counterparty the subscribing workspace could not otherwise learn.
//
// Every failure here is hard. A caller naming a message asked for this
// wiring; falling back to an unwired record would leave a component
// listening to nothing.
func Subscribe(ctx context.Context, opts SubscribeOptions) (*template.SubscribeBlock, error) {
	client, err := resolveClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return nil, err
	}
	res, err := client.Resolve(ctx, opts.Ref)
	if err != nil {
		return nil, err
	}
	channel, err := subscribeChannel(res, opts.PickChannel)
	if err != nil {
		return nil, err
	}
	return &template.SubscribeBlock{
		Message:       res.Message,
		Pubsub:        channel.Pubsub,
		Topic:         channel.Topic,
		Dataschema:    res.DataSchema,
		DataschemaURL: res.DataSchemaURL,
		// The counterparty, recorded once: which endpoint produces this
		// message and which group it belongs to. The subscribing workspace
		// cannot derive either, and assembly never re-asks the registry.
		Producer: channel.Endpoint,
		Group:    res.Group,
	}, nil
}

// Publishes resolves a message reference into the publishes block a
// producing component's scaffold record carries.
//
// The channel is not a choice here, unlike Subscribe: every channel on the
// message belongs to an existing producer, so picking one would make this
// component a second producer on someone else's channel. Zero producers
// can only mean the endpoint is not registered yet, and the remediation
// names that rather than a CLI fix.
func Publishes(ctx context.Context, opts PublishesOptions) (*template.PublishesBlock, error) {
	client, err := resolveClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return nil, err
	}
	res, err := client.Resolve(ctx, opts.Ref)
	if err != nil {
		return nil, err
	}
	channel, err := res.SubscribeChannel()
	if err != nil {
		var amb *xregistry.AmbiguousProducerError
		if errors.As(err, &amb) {
			return nil, fmt.Errorf("%w\na new producer cannot pick among existing channels; register the endpoint for this component in the registry first", amb)
		}
		var no *xregistry.NoProducerError
		if errors.As(err, &no) {
			return nil, fmt.Errorf("%w\nregister the producing endpoint for this component in the registry before scaffolding it", no)
		}
		return nil, err
	}
	return &template.PublishesBlock{
		Message:       res.Message,
		Pubsub:        channel.Pubsub,
		Topic:         channel.Topic,
		Dataschema:    res.DataSchema,
		DataschemaURL: res.DataSchemaURL,
		// The group, not the producer: the producing endpoint is this
		// component, so recording it would restate the record's identity.
		Group: res.Group,
	}, nil
}

