// contractLibrary is a loader that declares a shared-library dependency, and
// a stand-in for shared-contracts that renders its records from the
// `messages` reserved key.
//
// The mapping from schema type to language type lives here on purpose: it is
// the template library's decision, and this fixture stands in for a customer
// fork exercising it.
func contractLibrary(t *testing.T) *templatetest.Library {
	t.Helper()
	loader := `apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: message-loader
  labels:
    intropy.dev/block-kind: loader
    intropy.dev/message-params: message
spec:
  parameters:
    type: object
    required: [name, message, contract]
    properties:
      name:
        type: string
      message:
        type: string
      contract:
        type: string
        default: Order
  dependencies:
    - template: shared-contracts
      output: Contracts
      values:
        name: Contracts
        contract: '{{ .contract }}'
`
	shared := `apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: shared-contracts
  labels:
    intropy.dev/template-role: shared-library
spec:
  parameters:
    type: object
    required: [name]
    properties:
      name:
        type: string
      contract:
        type: string
        default: Order
      empty:
        type: boolean
        default: false
`
	// A .cs stand-in: one file for every record of every message, with the
	// type mapping the template owns.
	contracts := `namespace {{ .name }};
{{- if .messages }}
{{- range .messages }}
// {{ .message }} -> {{ .contract }} ({{ .schemaFile }})
{{- range .records }}
public sealed record {{ .name }}(
{{- range $i, $p := .properties }}
{{ if $i }},{{ end }}    {{ template "csType" $p }} {{ $p.name }}
{{- end }});
{{- end }}
{{- end }}
{{- else if .empty }}
public record {{ .contract }}();
{{- else }}
public record {{ .contract }}(string OrderId, decimal Total);
{{- end }}
{{- define "csType" -}}
{{- $t := "string" -}}
{{- if .ref }}{{ $t = .ref }}
{{- else if eq .schemaType "integer" }}{{ $t = "int" }}
{{- else if eq .schemaType "number" }}{{ $t = "decimal" }}
{{- else if and (eq .schemaType "string") (eq .format "date-time") }}{{ $t = "DateTimeOffset" }}
{{- end -}}
{{- if .array }}{{ $t = printf "IReadOnlyList<%s>" $t }}{{ end -}}
{{- $t }}{{ if not .required }}?{{ end -}}
{{- end -}}
`
	return templatetest.NewLibrary(t, "v1", map[string]string{
		"message-loader/template.yaml":              loader,
		"message-loader/skeleton/README.md.tmpl":    "{{ .name }} subscribes {{ .message }}\n",
		"shared-contracts/template.yaml":            shared,
		"shared-contracts/skeleton/Contracts.cs.tmpl": contracts,
		"shared-contracts/skeleton/{{ .name }}.csproj": "<Project Sdk=\"Microsoft.NET.Sdk\" />\n",
	})
}

// subscribeCreate scaffolds one loader subscribed to ref, into a component
// directory inside workspace.
func subscribeCreate(t *testing.T, lib *templatetest.Library, workspace, component, ref, contractName string) error {
	t.Helper()
	block, schema, err := message.Subscribe(context.Background(), message.SubscribeOptions{Ref: ref})
	if err != nil {
		t.Fatalf("message.Subscribe(%s): %v", ref, err)
	}
	return template.Create(context.Background(), template.CreateOptions{
		Template:  "message-loader",
		OutputDir: filepath.Join(workspace, component),
		SetValues: map[string]any{"name": component, "contract": contractName},
		NoInput:   true,
		Stderr:    os.Stderr,
		Source:    lib.Source(t),
		Subscribe: block,
		Schema:    schema,
	})
}

func readFile(t *testing.T, parts ...string) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(parts...))
	if err != nil {
		t.Fatalf("read %s: %v", filepath.Join(parts...), err)
	}
	return string(b)
}

