// Package contract records the payload schema a message pins, so a code
// generator can turn it into contract types.
//
// It generates nothing itself. The CLI's job ends at putting the schema
// document on disk with its provenance: which message it belongs to, which
// version is pinned, and which .NET type it is meant to produce. Turning
// JSON Schema into C# is a generator's job, and which generator — and what
// it maps a schema type onto — is the template library's decision, because
// customers fork the template library and never this CLI.
//
// The seam is Payload: the value injected under the `messages` reserved key,
// from which a skeleton renders the regeneration step for the project.
package contract

// Model is one message's contract provenance, as a render sees it.
type Model struct {
	Message       string
	Type          string
	Contract      string
	DataSchema    string
	DataSchemaURL string

	// SchemaFile is the committed document's path relative to the contracts
	// project root — the generator's input, so regenerating needs nothing
	// from the registry.
	SchemaFile string

	// document is the schema bytes as the registry served them, carried from
	// Build to Commit. Unexported: a model rebuilt from the index has
	// nothing to re-commit, and nothing outside this package should choose
	// what a project's schema file contains.
	document []byte
}

// Payload renders models as the `messages` reserved value: a list of maps
// with lowercase keys, matching the system-host payload's shape
// (internal/system/payload.go).
//
// Every key is always present, empty ones included — unlike that payload,
// which omits empties. Rendering runs with missingkey=error, so a skeleton
// reading a key that happens to be empty for one message would otherwise
// need a hasKey guard around every use.
func Payload(models []Model) []any {
	out := make([]any, len(models))
	for i, m := range models {
		out[i] = map[string]any{
			"message":       m.Message,
			"type":          m.Type,
			"contract":      m.Contract,
			"dataschema":    m.DataSchema,
			"dataschemaurl": m.DataSchemaURL,
			"schemaFile":    m.SchemaFile,
		}
	}
	return out
}
EOF
cat > internal/contract/generate.go <<'EOF'
package contract

import (
	"fmt"
	"sort"
)

// FormatJSONSchema is the one schema format the registry serves. The
// registry narrows its format attribute to this single value; a document in
// anything else is not one the generators the templates drive can read.
const FormatJSONSchema = "JsonSchema/draft/2020-12"

// Source is one resolved message's schema facts. It mirrors what a registry
// resolution produced without naming the registry's types, so this package
// stays independent of the client and easy to drive from a test.
type Source struct {
	Message       string
	Type          string
	Contract      string
	DataSchema    string
	DataSchemaURL string
	SchemaFormat  string
	Version       string
	Document      []byte
}

// Supported reports whether a message's declared schema format is one the
// template library's generator can read. A false means the registry widened
// its formats — a diagnostic for the caller, never a reason to fail a
// scaffold.
func Supported(format string) bool {
	// An empty format is the registry's own default for a JSON Schema
	// document, so it is read as one rather than refused.
	return format == "" || format == FormatJSONSchema
}

// Build turns one resolved message into its model. Nothing on disk is
// touched: the model has to exist before the render that creates the
// project it belongs to.
//
// The contract name is required, and is the template's own parameter — the
// registry has no opinion about .NET type names, and a generated type
// nothing references would be worse than no generated type.
func Build(src Source) (Model, error) {
	if len(src.Document) == 0 {
		return Model{}, fmt.Errorf("message %s: no schema document to generate from", src.Message)
	}
	if src.Contract == "" {
		return Model{}, fmt.Errorf("message %s: no contract name to generate", src.Message)
	}
	return Model{
		Message:       src.Message,
		Type:          src.Type,
		Contract:      src.Contract,
		DataSchema:    src.DataSchema,
		DataSchemaURL: src.DataSchemaURL,
		SchemaFile:    SchemaFileName(src.Message, src.Version),
		document:      src.Document,
	}, nil
}

// Commit writes the schema document and the index entry into a contracts
// project. It runs after the render, not before: the dependency render
// refuses a target directory holding files but no scaffold record, so
// seeding a document first would make the project look unmanaged.
func Commit(projectDir string, m Model) error {
	if len(m.document) == 0 {
		// A model rebuilt from the index is already committed; re-committing
		// it would truncate the document it names.
		return fmt.Errorf("message %s: model carries no schema document to commit", m.Message)
	}
	if err := WriteSchemaDocument(projectDir, m.SchemaFile, m.document); err != nil {
		return fmt.Errorf("write %s: %w", m.SchemaFile, err)
	}
	idx, err := LoadIndex(projectDir)
	if err != nil {
		return err
	}
	idx.Merge(Entry{
		Message:       m.Message,
		Type:          m.Type,
		Contract:      m.Contract,
		DataSchema:    m.DataSchema,
		DataSchemaURL: m.DataSchemaURL,
		SchemaFile:    m.SchemaFile,
	})
	return idx.Write(projectDir)
}

// Merge places one model into the set a project already carries, replacing
// the entry for the same message. The result is what a render sees; what the
// set was before is the baseline a re-render compares against.
func Merge(existing []Model, m Model) []Model {
	out := make([]Model, 0, len(existing)+1)
	replaced := false
	for _, e := range existing {
		if e.Message == m.Message {
			out = append(out, m)
			replaced = true
			continue
		}
		out = append(out, e)
	}
	if !replaced {
		out = append(out, m)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Message < out[j].Message })
	return out
}
EOF
