// records the pin, and leaves the project set up to run the generator.
func TestSubscribeCommitsSchemaAndGeneratorSetup(t *testing.T) {
	registry := contractRegistryFixture(t)
	t.Setenv("INTROPY_REGISTRY_URL", registry.URL)
	lib := contractLibrary(t)
	ws := t.TempDir()

	if err := subscribeCreate(t, lib, ws, "loader-export", "io.intropy.maxbo.product.export", "ExportEvent"); err != nil {
		t.Fatalf("create: %v", err)
	}
	contracts := filepath.Join(ws, "Contracts")

	// The document is committed exactly as the registry served it: the pin
	// names these bytes, and the generator reads them offline.
	relPath := contract.SchemaFileName("io.intropy.maxbo.product.export", "2")
	if got := readFile(t, contracts, filepath.FromSlash(relPath)); got != exportSchemaDoc {
		t.Errorf("committed document differs from what the registry served:\\n%s", got)
	}

	idx := loadIndex(t, contracts)
	if len(idx.Messages) != 1 {
		t.Fatalf("index = %+v, want one entry", idx.Messages)
	}
	e := idx.Messages[0]
	if e.Contract != "ExportEvent" || e.SchemaFile != relPath {
		t.Errorf("entry = %+v", e)
	}
	if !strings.HasSuffix(e.DataSchemaURL, "/versions/2") {
		t.Errorf("dataschemaurl = %q, want the pinned default version", e.DataSchemaURL)
	}

	// The generator step the template chose, rendered with this project's
	// namespace. Every argument it needs comes from the index at run time.
	script := readFile(t, contracts, "generate-contracts.ps1")
	for _, want := range []string{"quicktype", "--namespace Contracts", ".intropy/messages.json"} {
		if !strings.Contains(script, want) {
			t.Errorf("generator script is missing %q\\n%s", want, script)
		}
	}

	// No hand-written placeholder: the type comes from the generator, and a
	// project that does not compile until the step runs is better than one
	// that silently deserializes into the wrong shape.
	if _, err := os.Stat(filepath.Join(contracts, "ExportEvent.cs")); !os.IsNotExist(err) {
		t.Error("the placeholder must not be rendered when a schema will generate the type")
	}
}

// The case the design turns on: a second component in the same workspace
// subscribes to a second message. The Contracts project already exists, so
// the dependency render is skipped — and the second schema still has to land
// in it, with the index growing to match.
func TestSecondMessageLandsInTheExistingContractsProject(t *testing.T) {
	registry := contractRegistryFixture(t)
	t.Setenv("INTROPY_REGISTRY_URL", registry.URL)
	lib := contractLibrary(t)
	ws := t.TempDir()

	if err := subscribeCreate(t, lib, ws, "loader-export", "io.intropy.maxbo.product.export", "ExportEvent"); err != nil {
		t.Fatalf("first create: %v", err)
	}
	if err := subscribeCreate(t, lib, ws, "loader-price", "io.intropy.maxbo.product.price", "PriceChanged"); err != nil {
		t.Fatalf("second create: %v", err)
	}
	contracts := filepath.Join(ws, "Contracts")

	idx := loadIndex(t, contracts)
	if len(idx.Messages) != 2 {
		t.Fatalf("index = %+v, want both messages", idx.Messages)
	}
	if idx.Messages[0].Message != "io.intropy.maxbo.product.export" || idx.Messages[1].Message != "io.intropy.maxbo.product.price" {
		t.Errorf("index order = %+v, want sorted by message id", idx.Messages)
	}
	for _, m := range idx.Messages {
		if _, err := os.Stat(filepath.Join(contracts, filepath.FromSlash(m.SchemaFile))); err != nil {
			t.Errorf("schema document for %s: %v", m.Message, err)
		}
		if m.Contract == "" {
			t.Errorf("entry %s carries no contract name for the generator to use", m.Message)
		}
	}

	// One generator step covers both, because it reads the index rather than
	// being rendered per message.
	if got := strings.Count(readFile(t, contracts, "generate-contracts.ps1"), "quicktype"); got != 1 {
		t.Errorf("generator invocations = %d, want one loop over the index", got)
	}
}

// A hand-edited file in the shared project conflicts rather than being
// overwritten: several components depend on what that project says.
func TestSecondMessageConflictsWithALocalEdit(t *testing.T) {
	registry := contractRegistryFixture(t)
	t.Setenv("INTROPY_REGISTRY_URL", registry.URL)
	lib := contractLibrary(t)
	ws := t.TempDir()

	if err := subscribeCreate(t, lib, ws, "loader-export", "io.intropy.maxbo.product.export", "ExportEvent"); err != nil {
		t.Fatalf("first create: %v", err)
	}
	contracts := filepath.Join(ws, "Contracts")
	edited := "# hand-edited\\n" + readFile(t, contracts, "generate-contracts.ps1")
	if err := os.WriteFile(filepath.Join(contracts, "generate-contracts.ps1"), []byte(edited), 0o644); err != nil {
		t.Fatal(err)
	}

	err := subscribeCreate(t, lib, ws, "loader-price", "io.intropy.maxbo.product.price", "PriceChanged")
	if err == nil {
		t.Fatal("adding a message over a hand-edited file must fail rather than overwrite")
	}
	if !strings.Contains(err.Error(), "--force") {
		t.Errorf("err = %v, want it to name the way out", err)
	}
	if got := readFile(t, contracts, "generate-contracts.ps1"); got != edited {
		t.Error("the local edit must survive a refused update")
	}
	if len(loadIndex(t, contracts).Messages) != 1 {
		t.Error("a refused update must not record the message it did not commit")
	}
}

// --force is what the conflict error points at, so it has to work.
func TestForceTakesTheRegeneratedFile(t *testing.T) {
	registry := contractRegistryFixture(t)
	t.Setenv("INTROPY_REGISTRY_URL", registry.URL)
	lib := contractLibrary(t)
	ws := t.TempDir()

	if err := subscribeCreate(t, lib, ws, "loader-export", "io.intropy.maxbo.product.export", "ExportEvent"); err != nil {
		t.Fatalf("first create: %v", err)
	}
	contracts := filepath.Join(ws, "Contracts")
	if err := os.WriteFile(filepath.Join(contracts, "generate-contracts.ps1"), []byte("# hand-edited\\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	if err := subscribeCreateForce(t, lib, ws, "loader-price", "io.intropy.maxbo.product.price", "PriceChanged", true); err != nil {
		t.Fatalf("create --force over a local edit: %v", err)
	}
	if strings.Contains(readFile(t, contracts, "generate-contracts.ps1"), "hand-edited") {
		t.Error("--force takes the regenerated file, so the edit is gone")
	}
	if len(loadIndex(t, contracts).Messages) != 2 {
		t.Error("both messages are recorded once the render succeeded")
	}
}

// A message the registry describes without a schema scaffolds exactly as it
// did before any of this existed: the template's own placeholder, no
// documents, no index.
func TestSubscribeWithoutASchemaChangesNothing(t *testing.T) {
	registry := contractRegistryFixture(t)
	t.Setenv("INTROPY_REGISTRY_URL", registry.URL)
	lib := contractLibrary(t)
	ws := t.TempDir()

	if err := subscribeCreate(t, lib, ws, "loader-ping", "io.intropy.maxbo.product.ping", "Ping"); err != nil {
		t.Fatalf("create: %v", err)
	}
	contracts := filepath.Join(ws, "Contracts")

	if got := readFile(t, contracts, "Ping.cs"); !strings.Contains(got, "record Ping(string OrderId") {
		t.Errorf("want the template's own placeholder, got:\\n%s", got)
	}
	if _, err := os.Stat(filepath.Join(contracts, contract.SchemaDirName)); !os.IsNotExist(err) {
		t.Error("a message with no schema commits no document")
	}
	if len(loadIndex(t, contracts).Messages) != 0 {
		t.Error("a message with no schema records no index entry")
	}
}

// The index is the generator's input and the project's own record, so it must
// be valid JSON that a tool outside this CLI can read.
func TestIndexIsReadableJSON(t *testing.T) {
	registry := contractRegistryFixture(t)
	t.Setenv("INTROPY_REGISTRY_URL", registry.URL)
	lib := contractLibrary(t)
	ws := t.TempDir()

	if err := subscribeCreate(t, lib, ws, "loader-export", "io.intropy.maxbo.product.export", "ExportEvent"); err != nil {
		t.Fatalf("create: %v", err)
	}
	raw := readFile(t, ws, "Contracts", filepath.FromSlash(contract.IndexRelPath))
	var doc struct {
		SchemaVersion int `json:"schemaVersion"`
		Messages      []struct {
			Message    string `json:"message"`
			Contract   string `json:"contract"`
			SchemaFile string `json:"schemaFile"`
		} `json:"messages"`
	}
	if err := json.Unmarshal([]byte(raw), &doc); err != nil {
		t.Fatalf("index is not valid JSON: %v\\n%s", err, raw)
	}
	if doc.SchemaVersion != contract.IndexSchemaVersion {
		t.Errorf("schemaVersion = %d", doc.SchemaVersion)
	}
	// The three fields a generator invocation needs.
	m := doc.Messages[0]
	if m.Message == "" || m.Contract == "" || m.SchemaFile == "" {
		t.Errorf("entry = %+v, want message, contract and schemaFile", m)
	}
}
