package template

import (
	"fmt"
	"io"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/contract"
)

// The contract half of a render: what a shared-library project gets told
// about the messages it holds types for, and how a project that already
// exists learns about a new one.
//
// Only shared-library projects are involved. A component's own skeleton
// references the contract type by name; the type itself lives in the shared
// sibling, which is the only project whose contents grow as more components
// subscribe.
//
// Nothing here emits C#. The render receives the message list and the
// committed schema documents, and the skeleton decides what to do with them
// — in practice, set up the generator that produces the types.

// contractPlan is the per-run contract state a dependency render needs: the
// model this run resolved, if any, and the writer diagnostics go to.
type contractPlan struct {
	model  *contract.Model
	stderr io.Writer
}

// buildContractPlan turns the resolved schema into the model a render
// consumes. A run with no schema — no message flag, a message without a
// schema pin, an unreadable format, or a template that declares no contract
// name — plans nothing, and every render behaves as it did before contract
// generation existed.
func buildContractPlan(src *contract.Source, values map[string]any, stderr io.Writer) (*contractPlan, error) {
	plan := &contractPlan{stderr: stderr}
	if src == nil {
		return plan, nil
	}
	if !contract.Supported(src.SchemaFormat) {
		// Not fatal: the wiring resolved, and refusing to scaffold over a
		// schema format the generators cannot read would make a registry
		// that widened its formats unusable.
		fmt.Fprintf(stderr, "warning: message %s pins a %s schema, which the contract generator cannot read — contract types stay as the template renders them\n", src.Message, src.SchemaFormat)
		return plan, nil
	}

	// The .NET type name is the template's own parameter, resolved by now.
	// A template that declares none has no type for a generator to produce.
	s := *src
	s.Contract = stringValue(values, KeyContract)
	if s.Contract == "" {
		fmt.Fprintf(stderr, "warning: message %s pins a schema but the template declares no %s parameter — nothing to generate a type as\n", src.Message, KeyContract)
		return plan, nil
	}
	m, err := contract.Build(s)
	if err != nil {
		return nil, err
	}
	plan.model = &m
	return plan, nil
}

// wants reports whether this template's output is where contract types live.
func (p *contractPlan) wants(tmpl *Template) bool {
	return roleFromLabels(tmpl.Metadata.Labels) == RoleSharedLibrary
}

// inject adds the messages a shared-library render needs — the models
// already on disk plus this run's, if any.
//
// It runs for every shared-library render, including one that resolved no
// schema: rendering uses missingkey=error, so a skeleton that reads
// .messages must find the key whether or not there is anything in it.
func (p *contractPlan) inject(tmpl *Template, values map[string]any, projectDir string) ([]contract.Model, error) {
	if !p.wants(tmpl) {
		return nil, nil
	}
	models, err := contract.LoadModels(projectDir)
	if err != nil {
		return nil, err
	}
	if p.model != nil {
		models = contract.Merge(models, *p.model)
	}
	if err := injectMessages(tmpl, values, models); err != nil {
		return nil, err
	}
	return models, nil
}

// injectMessages puts one model set into a value map under the reserved key.
func injectMessages(tmpl *Template, values map[string]any, models []contract.Model) error {
	return InjectReserved(tmpl, values, map[string]any{
		ReservedMessagesKey: contract.Payload(models),
	})
}

// commit writes this run's schema document and index entry into the project
// the render just produced. It runs after the render because the dependency
// flow refuses a target directory holding files but no scaffold record —
// seeding a document first would make the project look unmanaged.
func (p *contractPlan) commit(tmpl *Template, projectDir string) error {
	if p.model == nil || !p.wants(tmpl) {
		return nil
	}
	if err := contract.Commit(projectDir, *p.model); err != nil {
		return err
	}
	fmt.Fprintf(p.stderr, "generated contract %s from %s\n", p.model.Contract, p.model.DataSchemaURL)
	return nil
}

// updateProject re-renders an existing shared-library project so it gains
// this run's message.
//
// The baseline is the project as its committed messages alone describe it:
// a file matching that differs from the new render only by the message being
// added, so it updates. A file matching neither has been edited by hand and
// conflicts, which is reported rather than overwritten — the whole point of
// a shared project is that several components depend on what it says.
func (p *contractPlan) updateProject(depRoot string, tmpl *Template, sets map[string]any, projectDir string, force bool) error {
	if p.model == nil || !p.wants(tmpl) {
		return nil
	}

	existing, err := contract.LoadModels(projectDir)
	if err != nil {
		return err
	}
	baseline, err := contractValues(tmpl, sets, existing)
	if err != nil {
		return err
	}
	merged, err := contractValues(tmpl, sets, contract.Merge(existing, *p.model))
	if err != nil {
		return err
	}

	outcomes, err := RenderUpdate(filepath.Join(depRoot, templateSkeletonDir), projectDir, merged, tmpl.Spec.Files, RenderUpdateOptions{
		Baseline: baseline,
		Force:    force,
	})
	if err != nil {
		return err
	}
	for _, o := range outcomes {
		switch o.Outcome {
		case OutcomeConflict:
			return fmt.Errorf("%s in %s has local edits that adding message %s would overwrite\nre-run with --force to take the regenerated file, or move the edits out of the generated type", o.Path, filepath.Base(projectDir), p.model.Message)
		case OutcomeCreated, OutcomeUpdated:
			fmt.Fprintf(p.stderr, "%s %s/%s\n", o.Outcome, filepath.Base(projectDir), o.Path)
		}
	}
	return nil
}

// contractValues resolves one shared-library template against a value set
// with the given models injected — the render input for both halves of an
// update comparison.
func contractValues(tmpl *Template, sets map[string]any, models []contract.Model) (map[string]any, error) {
	values, err := Resolve(tmpl, nil, nil, sets, nil)
	if err != nil {
		return nil, err
	}
	if err := injectMessages(tmpl, values, models); err != nil {
		return nil, err
	}
	return values, nil
}

// stringValue reads one string from a resolved value map, tolerating a
// missing or non-string entry: every caller here treats absence as "the
// template does not declare it".
func stringValue(values map[string]any, key string) string {
	if v, ok := values[key]; ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return ""
}

