//go:build e2e

package system

// Renders the real shared-contracts and loader templates from a local
// intropy-templates checkout, with and without the messages the CLI injects
// for a registry-described message. Run with:
//
//	INTROPY_TEMPLATES_DIR=~/dev/intropy/integrio-intropy/intropy-templates \
//	  go test -tags e2e ./internal/system/ -run TestRealContract -v

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/contract"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// renderRealTemplate resolves one template from the local library and renders
// it, injecting the messages payload the CLI would inject for a shared
// library. A nil models slice still injects the key: an empty list is what a
// run that resolved no schema produces, and the skeleton must read it.
func renderRealTemplate(t *testing.T, name string, sets map[string]any, models []contract.Model, inject bool) string {
	t.Helper()
	lib := templatesDir(t)
	tmpl, err := template.LoadTemplate(filepath.Join(lib, name, "template.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	values, err := template.Resolve(tmpl, nil, nil, sets, nil)
	if err != nil {
		t.Fatalf("resolve %s: %v", name, err)
	}
	if inject {
		if err := template.InjectReserved(tmpl, values, map[string]any{
			template.ReservedMessagesKey: contract.Payload(models),
		}); err != nil {
			t.Fatalf("inject: %v", err)
		}
	}
	out := t.TempDir()
	if err := template.RenderFiltered(filepath.Join(lib, name, "skeleton"), out, values, tmpl.Spec.Files); err != nil {
		t.Fatalf("render %s: %v", name, err)
	}
	return out
}

func exportModel() contract.Model {
	return contract.Model{
		Message:       "io.intropy.maxbo.product.export",
		Type:          "io.intropy.maxbo.product.export",
		Contract:      "ExportEvent",
		DataSchema:    "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1",
		DataSchemaURL: "https://registry.intropy.io/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1/versions/2",
		SchemaFile:    "schemas/io.intropy.maxbo.product.export.v2.json",
	}
}

func exists(t *testing.T, dir, rel string) bool {
	t.Helper()
	_, err := os.Stat(filepath.Join(dir, filepath.FromSlash(rel)))
	return err == nil
}

func read(t *testing.T, dir, rel string) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join(dir, filepath.FromSlash(rel)))
	if err != nil {
		t.Fatalf("read %s: %v", rel, err)
	}
	return string(b)
}

// With a schema, the shared library stops rendering the hand-written record
// and renders the generator step instead.
func TestRealContractsGenerated(t *testing.T) {
	out := renderRealTemplate(t, "shared-contracts",
		map[string]any{"name": "Contracts", "contract": "ExportEvent"},
		[]contract.Model{exportModel()}, true)

	if exists(t, out, "ExportEvent.cs") {
		t.Error("the hand-written record must step aside for the generated one")
	}
	if exists(t, out, "OrderLine.cs") {
		t.Error("the sample's nested record must step aside too")
	}
	if !exists(t, out, "ContractOptions.cs") {
		t.Fatal("the serialization seam must be rendered")
	}

	script := read(t, out, "generate-contracts.ps1")
	for _, want := range []string{"quicktype@23", "--top-level", ".intropy/messages.json", "--namespace 'Contracts'"} {
		if !strings.Contains(script, want) {
			t.Errorf("generator script is missing %q\n%s", want, script)
		}
	}

	if got := read(t, out, "ContractOptions.cs"); !strings.Contains(got, "namespace Contracts;") {
		t.Errorf("ContractOptions renders into the wrong namespace:\n%s", got)
	}

	if doc := read(t, out, "README.md"); !strings.Contains(doc, "ExportEvent") ||
		!strings.Contains(doc, "generate-contracts.ps1") {
		t.Error("the README must name the generated contract and the step that produces it")
	}
}

// Without a schema — an internal event, or no message at all — the library
// renders exactly as it did before any of this existed.
func TestRealContractsHandWritten(t *testing.T) {
	out := renderRealTemplate(t, "shared-contracts",
		map[string]any{"name": "Contracts", "contract": "Order"}, nil, true)

	if !exists(t, out, "Order.cs") {
		t.Error("with no schema the hand-written record is still the contract")
	}
	if !exists(t, out, "OrderLine.cs") {
		t.Error("the sample's nested record renders with it")
	}
	if exists(t, out, "generate-contracts.ps1") || exists(t, out, "ContractOptions.cs") {
		t.Error("a project with nothing to generate gets no generator")
	}
}

// A mixed system: the project holds a generated external contract, and a
// component whose own contract is hand-written still gets its sample.
func TestRealContractsMixedKeepsTheHandWrittenOne(t *testing.T) {
	out := renderRealTemplate(t, "shared-contracts",
		map[string]any{"name": "Contracts", "contract": "ProductExported"},
		[]contract.Model{exportModel()}, true)

	if !exists(t, out, "ProductExported.cs") {
		t.Error("a contract with no schema of its own keeps its hand-written record")
	}
	if !exists(t, out, "generate-contracts.ps1") {
		t.Error("the generator still renders for the message that does have a schema")
	}
}

// An older CLI injects no messages at all; the templates must still render.
func TestRealContractsWithoutTheReservedKey(t *testing.T) {
	out := renderRealTemplate(t, "shared-contracts",
		map[string]any{"name": "Contracts", "contract": "Order"}, nil, false)

	if !exists(t, out, "Order.cs") {
		t.Error("a render with no messages key at all must still produce the contract")
	}
}

// The loader's step bodies compile against a generated contract: they read
// the contract project's options and touch none of the sample's fields.
func TestRealLoaderStepsAgainstAGeneratedContract(t *testing.T) {
	out := renderRealTemplate(t, "loader", map[string]any{
		"name":     "Loader.Product",
		"contract": "ExportEvent",
		"subscribe": map[string]any{
			"message":       "io.intropy.maxbo.product.export",
			"pubsub":        "product-distribution-pubsub",
			"topic":         "sbt-test-product-extractor-001",
			"dataschema":    "/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1",
			"dataschemaurl": "https://registry.intropy.io/schemagroups/io.intropy.maxbo.product/schemas/product-export.v1/versions/2",
		},
	}, nil, false)

	des := read(t, out, "src/Process/Deserializer.cs")
	if !strings.Contains(des, "ContractOptions.Options") {
		t.Errorf("the deserializer must read through the contract project's options:\n%s", des)
	}
	for _, forbidden := range []string{"order.OrderId", "order.OrderDate"} {
		if strings.Contains(des, forbidden) {
			t.Errorf("the generated branch must not touch the sample contract's fields (%s)", forbidden)
		}
	}
	if val := read(t, out, "src/Process/Validator.cs"); strings.Contains(val, "order.OrderId") {
		t.Error("the validator must not touch the sample contract's fields either")
	}
}

// And without a schema the loader is byte-for-byte the scaffold it was.
func TestRealLoaderStepsWithoutASchema(t *testing.T) {
	out := renderRealTemplate(t, "loader", map[string]any{
		"name":     "Loader.Order",
		"contract": "Order",
		"topic":    "orders",
	}, nil, false)

	des := read(t, out, "src/Process/Deserializer.cs")
	if !strings.Contains(des, "order.OrderId") {
		t.Errorf("the sample body is what an internal event still gets:\n%s", des)
	}
	if strings.Contains(des, "ContractOptions") {
		t.Error("a hand-written contract needs no generated serialization seam")
	}
}

